t.script:
// Define basic currency function immediately - before any other code
window.getSafeCurrency = window.getSafeCurrency || function(serviceId) { return '$'; };
window.getServiceCurrency = window.getServiceCurrency || function(serviceId) { return '$'; };

// Initialize currency functions immediately
(function() {
    // Global currency symbol for dynamic pricing
    const COMPANY_CURRENCY = '';
    window.COMPANY_CURRENCY = COMPANY_CURRENCY;

    // Service-specific currencies
    const SERVICE_CURRENCIES = ;
    window.SERVICE_CURRENCIES = SERVICE_CURRENCIES;

    // Function to get currency for a specific service
    window.getServiceCurrency = function(serviceId) {
    try {
        // Ensure SERVICE_CURRENCIES exists
        if (typeof SERVICE_CURRENCIES === 'undefined') {
            return COMPANY_CURRENCY || '$';
        }
        return SERVICE_CURRENCIES[serviceId] || COMPANY_CURRENCY || '$';
    } catch (e) {
        return COMPANY_CURRENCY || '$';
    }
};

// Ensure the function is immediately available globally
if (!window.getServiceCurrency) {
    window.getServiceCurrency = function(serviceId) {
        return '$'; // Fallback
    };
}

// Define a safe currency getter function
window.getSafeCurrency = function(serviceId) {
    try {
        if (typeof window.getServiceCurrency === 'function') {
            return window.getServiceCurrency(serviceId);
        }
        // Ultimate fallback
        return COMPANY_CURRENCY || '$';
    } catch (e) {
        return '$';
    }
};
})(); // End of IIFE

// Global function for service selection
window.selectService = function(element) {
    const serviceId = element.dataset.serviceId;
    const serviceType = element.dataset.serviceType;

    // Store selected service ID for currency lookup
    window.selectedServiceId = parseInt(serviceId);

    // Store service selection in sessionStorage for navigation
    const serviceData = {
        id: serviceId,
        type: serviceType
    };

    sessionStorage.setItem('selectedService', JSON.stringify(serviceData));

    // Navigate to calendar page with service selected
    window.location.href = `/appointment/booking/calendar?service_id=${serviceId}`;
};

// Ultra-early currency function definition
window.getSafeCurrency = function(serviceId) { return ''; };
window.getServiceCurrency = function(serviceId) { return ''; };

div.script:
// 
    // Cart badge update function
    function updateCartBadge(cartQuantity) {
        const badges = document.querySelectorAll('.my_cart_quantity');
        badges.forEach(badge => {
            badge.textContent = cartQuantity;
            // Show/hide badge based on quantity
            if (cartQuantity === 0) {
                badge.classList.add('d-none');
                // Hide cart container if quantity is 0
                const cartContainer = badge.closest('.o_wsale_my_cart');
                if (cartContainer) cartContainer.classList.add('d-none');
            } else {
                badge.classList.remove('d-none');
                // Show cart container if quantity > 0
                const cartContainer = badge.closest('.o_wsale_my_cart');
                if (cartContainer) cartContainer.classList.remove('d-none');

                // Add animation like Odoo does
                badge.classList.add('o_mycart_zoom_animation');
                setTimeout(() => {
                    badge.classList.remove('o_mycart_zoom_animation');
                }, 300);
            }
        });

        // Update session storage like Odoo does
        if (typeof Storage !== 'undefined') {
            sessionStorage.setItem('website_sale_cart_quantity', cartQuantity);
        }
    }

    let currentEmployees = {};
    let currentSlots = {};
    let selectedSlot = null;
    let currentService = null;
    let availableDates = [];
    let selectedDate = null;
    let selectedEmployee = null; // Track selected employee
    let currentDateOffset = 0; // Track current week offset
    let currentEmployeePage = 0; // Track current employee page
    let employeesPerPage = 3; // Show 3 employees at a time
    let currentBranchId = 1; // Dynamic branch ID, will be updated from service plans
    let isPackageBooking = false; // Track if current selection is a package
    let packageServices = {}; // Store package services data
    let packageBookingData = {}; // Store booking data for each service in package
    let selectedPackageId = null; // Store the selected package ID
    let packageServicesList = []; // Ordered list of package services
    let currentPackageServiceIndex = 0; // Current service index in package
    let employeeAvailability = {}; // Track which employees have available slots
    let employeeSlotData = {}; // Store API slot data per employee for multi-slot booking
    let isActiveBookingFlow = false; // Track if we're in active booking mode (service + location selected)
    let isPopulatingFilters = false; // Flag to prevent infinite loops during filter population
    let packageUsedSlots = new Set(); // Track slots used in package booking to prevent conflicts

    // Translation system for dynamic language support
    const translations = {
        'ar': {
            'available': 'متاح',
            'unavailable': 'غير متاح',
            'not_available': 'غير متاح',
            'available_professionals': 'المختصون المتاحون',
            'loading_available_slots': 'جاري تحميل الأوقات المتاحة...',
            'click_available_slot': 'اضغط على أي وقت متاح لحجز موعدك',
            'select_location_view_times': 'اختر الموقع لعرض الأوقات المتاحة',
            'no_available_slots_date': 'لا توجد أوقات متاحة لهذا التاريخ',
            'used_in_package': 'مستخدم في الباقة',
            'package_service': 'خدمة الباقة',
            'package_service_number': 'خدمة الباقة',
            'booking_package_service': 'جاري حجز خدمة الباقة...',
            'of': 'من',
            'service_selected': 'اختيار الخدمة',
            'appointment_added_cart': 'تم إضافة الموعد للسلة بنجاح!',
            'package_added_cart': 'تم إضافة الباقة الكاملة للسلة بنجاح!',
            'service_booked_next': 'تم حجز الخدمة! الانتقال للخدمة التالية...',
            'select_service_date_first': 'يرجى اختيار الخدمة والتاريخ أولاً.',
            'select_time_slot_first': 'يرجى اختيار فترة زمنية أولاً.',
            'slot_already_selected': 'تم اختيار هذا الموعد بالفعل لخدمة أخرى في الباقة. يرجى اختيار موعد مختلف.',
            'select_required_info': 'يرجى اختيار جميع المعلومات المطلوبة أولاً.',
            'error_loading_package_services': 'خطأ في تحميل خدمات الباقة.',
            'no_services_in_package': 'لا توجد خدمات في هذه الباقة.',
            'error_adding_cart': 'خطأ في إضافة الموعد للسلة. يرجى المحاولة مرة أخرى.',
            'network_error': 'خطأ في الشبكة:',
            'error': 'خطأ:',
            'ready_add_service': 'جاهز لإضافة خدمة أخرى أو المتابعة للدفع',
            'proceed_to': 'الانتقال إلى',
            'cancel': 'إلغاء',
            'next_service': 'الخدمة التالية',
            'back_to_previous_service': 'العودة للخدمة السابقة',
            'package_selected': 'تم اختيار الباقة',
            'book_your_appointment': 'حجز موعدك',
            'reset_all': 'إعادة تعيين الكل',
            'click_reset_all_exit_package': 'انقر على "{reset_all}" للخروج من وضع الباقة واختيار خدمة أخرى',
            'add_to_cart': 'أضف للسلة'
        },
        'en': {
            'available': 'Available',
            'unavailable': 'Unavailable', 
            'not_available': 'Not Available',
            'available_professionals': 'Available Professionals',
            'loading_available_slots': 'Loading available time slots...',
            'click_available_slot': 'Click on any available time slot to book your appointment',
            'select_location_view_times': 'Select location to view available times',
            'no_available_slots_date': 'No available slots for this date',
            'used_in_package': 'Used in Package',
            'package_service': 'Package Service',
            'package_service_number': 'Package Service',
            'booking_package_service': 'Booking package service...',
            'of': 'of',
            'service_selected': 'Service Selected',
            'appointment_added_cart': 'Appointment added to cart successfully!',
            'package_added_cart': 'Complete package added to cart successfully!',
            'service_booked_next': 'Service booked! Moving to next service...',
            'select_service_date_first': 'Please select a service and date first.',
            'select_time_slot_first': 'Please select a time slot first.',
            'slot_already_selected': 'This time slot has already been selected for another service in this package. Please choose a different time.',
            'select_required_info': 'Please select all required information first.',
            'error_loading_package_services': 'Error loading package services.',
            'no_services_in_package': 'No services found in this package.',
            'error_adding_cart': 'Error adding appointment to cart. Please try again.',
            'network_error': 'Network error:',
            'error': 'Error:',
            'ready_add_service': 'Ready to add another service or proceed to payment',
            'proceed_to': 'Proceed to',
            'cancel': 'Cancel',
            'next_service': 'Next Service',
            'back_to_previous_service': 'Back to Previous Service',
            'package_selected': 'Package Selected',
            'book_your_appointment': 'Book Your Appointment',
            'reset_all': 'Reset All',
            'click_reset_all_exit_package': 'Click "{reset_all}" to exit package mode and select a different service',
            'add_to_cart': 'Add to Cart'
        }
    };

    // Function to get current website language
    function getCurrentLanguage() {
        // Check HTML lang attribute
        const htmlLang = document.documentElement.lang || document.documentElement.getAttribute('lang');
        if (htmlLang) {
            return htmlLang.toLowerCase().startsWith('ar') ? 'ar' : 'en';
        }

        // Check Odoo website language from body class or data attributes
        const body = document.body;
        if (body.classList.contains('o_rtl') || body.classList.contains('rtl') || 
            body.getAttribute('dir') === 'rtl') {
            return 'ar';
        }

        // Check URL for language code
        const urlLang = window.location.pathname.match(/^\/([a-z]{2})\//);
        if (urlLang && urlLang[1] === 'ar') {
            return 'ar';
        }

        // Check browser language as fallback
        const browserLang = navigator.language || navigator.userLanguage;
        if (browserLang && browserLang.toLowerCase().startsWith('ar')) {
            return 'ar';
        }

        // Default to English
        return 'en';
    }

    // Function to get translated text
    function t(key) {
        const lang = getCurrentLanguage();
        return translations[lang] && translations[lang][key] ? translations[lang][key] : translations['en'][key] || key;
    }

    // Function to get formatted reset instructions text
    function getResetInstructionsText() {
        const resetAllText = t('reset_all');
        const templateText = t('click_reset_all_exit_package');
        return templateText.replace('{reset_all}', resetAllText);
    }

    // Service card enable/disable functions
    function disableAllServicesExcept(selectedServiceId) {

        // Show reset instructions when services are disabled (package mode)
        showResetInstructions();

        const serviceCards = document.querySelectorAll('.service-card');
        serviceCards.forEach(card => {
            const cardServiceId = card.getAttribute('data-service-id');

            if (cardServiceId !== selectedServiceId) {
                // Disable the card
                card.classList.add('disabled-service');
                card.style.opacity = '0.3';
                card.style.pointerEvents = 'none';
                card.style.cursor = 'not-allowed';
                card.style.filter = 'grayscale(80%)';

                // Add a subtle blur effect
                card.style.transform = 'scale(0.98)';

                // Add disabled overlay
                if (!card.querySelector('.disabled-overlay')) {
                    const overlay = document.createElement('div');
                    overlay.className = 'disabled-overlay';
                    overlay.style.cssText = `
                        position: absolute;
                        top: 0;
                        left: 0;
                        right: 0;
                        bottom: 0;
                        background: rgba(255, 255, 255, 0.8);
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        z-index: 10;
                        border-radius: inherit;
                    `;

                    const lang = getCurrentLanguage();
                    const disabledText = lang === 'ar' ? 'غير متاح أثناء اختيار الباقة' : 'Not available during package selection';

                    overlay.innerHTML = `
                        <div class="text-center p-2">
                            <i class="fa fa-lock fa-2x text-muted mb-2"></i>
                            <div class="small text-muted">${disabledText}</div>
                        </div>
                    `;

                    // Ensure card has relative positioning
                    if (!card.style.position || card.style.position === 'static') {
                        card.style.position = 'relative';
                    }

                    card.appendChild(overlay);
                }
            } else {
                // Highlight the selected service
                card.style.boxShadow = '0 0 20px rgba(0, 123, 255, 0.6)';
                card.style.borderColor = '#C76E49';
                card.style.borderWidth = '3px';
                card.style.borderStyle = 'solid';

                // Add selected badge if not exists
                if (!card.querySelector('.selected-service-badge')) {
                    const selectedBadge = document.createElement('div');
                    selectedBadge.className = 'selected-service-badge position-absolute';
                    selectedBadge.style.cssText = `
                        top: 5px;
                        right: 5px;
                        z-index: 15;
                        background: #C76E49;
                        color: white;
                        padding: 4px 8px;
                        border-radius: 12px;
                        font-size: 12px;
                        font-weight: bold;
                    `;

                    const lang = getCurrentLanguage();
                    selectedBadge.textContent = lang === 'ar' ? 'مختار' : 'Selected';

                    // Ensure card has relative positioning
                    if (!card.style.position || card.style.position === 'static') {
                        card.style.position = 'relative';
                    }

                    card.appendChild(selectedBadge);
                }
            }
        });
    }

    function enableAllServices() {
        const serviceCards = document.querySelectorAll('.service-card');
        serviceCards.forEach(card => {
            // Remove disabled styling
            card.classList.remove('disabled-service');
            card.style.opacity = '';
            card.style.pointerEvents = '';
            card.style.cursor = '';
            card.style.filter = '';
            card.style.transform = '';
            card.style.boxShadow = '';
            card.style.borderColor = '';
            card.style.borderWidth = '';
            card.style.borderStyle = '';

            // Remove disabled overlay
            const overlay = card.querySelector('.disabled-overlay');
            if (overlay) {
                overlay.remove();
            }

            // Remove selected service badge
            const selectedBadge = card.querySelector('.selected-service-badge');
            if (selectedBadge) {
                selectedBadge.remove();
            }
        });

        // Hide reset instructions when services are enabled
        hideResetInstructions();
    }

    function showResetInstructions() {
        const instructionsDiv = document.getElementById('resetInstructionsMessage');
        if (instructionsDiv) {
            instructionsDiv.style.display = 'block';

            // Update the instruction text with translations
            const resetInstructionsTexts = instructionsDiv.querySelectorAll('.reset-instructions-text');
            const translatedText = getResetInstructionsText();

            resetInstructionsTexts.forEach(textElement => {
                textElement.textContent = translatedText;
            });

            // Show appropriate language section
            const lang = getCurrentLanguage();
            const arDiv = instructionsDiv.querySelector('.package-reset-info-ar');
            const enDiv = instructionsDiv.querySelector('.package-reset-info-en');

            if (lang === 'ar' && arDiv) {
                arDiv.style.display = 'block';
                if (enDiv) enDiv.style.display = 'none';
            } else if (enDiv) {
                enDiv.style.display = 'block';
                if (arDiv) arDiv.style.display = 'none';
            }
        }
    }

    function hideResetInstructions() {
        const instructionsDiv = document.getElementById('resetInstructionsMessage');
        if (instructionsDiv) {
            instructionsDiv.style.display = 'none';
        }
    }


    // Loading screen functions
    function showLoadingScreen(message = 'Loading...') {
        // Remove existing loading screen if any
        const existingLoading = document.getElementById('globalLoadingScreen');
        if (existingLoading) {
            existingLoading.remove();
        }

        const loadingDiv = document.createElement('div');
        loadingDiv.id = 'globalLoadingScreen';
        loadingDiv.className = 'position-fixed w-100 h-100 d-flex align-items-center justify-content-center';
        loadingDiv.style.cssText = 'top: 0; left: 0; background: rgba(0,0,0,0.5); z-index: 99999;';
        loadingDiv.innerHTML = `
            <div class="bg-white p-4 rounded text-center">
                <div class="spinner-border text-primary mb-3" role="status"></div>
                <div class="text-dark">${message}</div>
            </div>
        `;
        document.body.appendChild(loadingDiv);
    }

    function hideLoadingScreen() {
        const loadingDiv = document.getElementById('globalLoadingScreen');
        if (loadingDiv) {
            loadingDiv.remove();
        }
    }

    // Reset functions for data clearing
    function resetLocationData() {
        // Clear location selection
        const locationCards = document.querySelectorAll('.location-card');
        locationCards.forEach(card => {
            card.classList.remove('selected');
            card.style.borderColor = 'transparent';
        });

        // Reset location hidden inputs
        const locationInput = document.getElementById('currentLocationInput');
        if (locationInput) locationInput.value = '';

        const locationSelect = document.getElementById('locationSelect');
        if (locationSelect) locationSelect.value = '';

        // Hide location sections
        const locationSelectionSection = document.getElementById('locationSelectionSection');
        if (locationSelectionSection) locationSelectionSection.style.display = 'none';

        const addressSection = document.getElementById('addressSection');
        if (addressSection) addressSection.style.display = 'none';
    }

    function resetDateData() {
        // Reset date selection
        selectedDate = null;
        currentDateOffset = 0;

        // Clear date styling
        const dateCards = document.querySelectorAll('.date-card');
        dateCards.forEach(card => {
            card.classList.remove('selected');
            card.style.borderColor = 'transparent';
        });

        // Reset date input
        const dateInput = document.getElementById('currentDateInput');
        if (dateInput) dateInput.value = '';

        // Hide date section
        const dateSection = document.getElementById('dateSection');
        if (dateSection) dateSection.style.display = 'none';

        // Reload date slider to today
        loadDateSlider();
    }

    function resetCalendarData() {
        // Clear calendar data
        currentEmployees = {};
        currentSlots = {};
        selectedSlot = null;
        selectedEmployee = null;
        currentEmployeePage = 0;
        employeeAvailability = {};
        packageUsedSlots.clear(); // Clear package slot conflicts tracking

        // Clear calendar UI
        const calendarTable = document.getElementById('calendarTable');
        if (calendarTable) {
            const tbody = calendarTable.querySelector('tbody');
            if (tbody) tbody.innerHTML = `<tr><td colspan="100%" class="text-center text-muted">${t('select_location_view_times')}</td></tr>`;
        }

        // Clear employee headers
        const employeeHeaders = document.getElementById('employeeHeaders');
        if (employeeHeaders) employeeHeaders.innerHTML = '';

        // Don't hide calendar sections if we're in active booking flow
        if (!isActiveBookingFlow) {
            // Only hide sections if we're not in active booking flow
            const calendarMainSection = document.getElementById('calendarMainSection');
            if (calendarMainSection) calendarMainSection.style.display = 'none';

            const calendarContainer = document.getElementById('calendarContainer');
            if (calendarContainer) calendarContainer.style.display = 'none';
        }

        // Note: Don't hide filters here - they should remain visible during booking flow

        // Clear any selection info
        const currentSelection = document.getElementById('currentSelection');
        if (currentSelection) currentSelection.style.display = 'none';
    }

    function resetAllBookingData() {
        isActiveBookingFlow = false; // Exit active booking mode
        resetLocationData();
        resetDateData();
        resetCalendarData();
    }

    function resetAfterLocationChange() {
        resetDateData();
        resetCalendarData();
    }

    function resetAfterCartSuccess() {
        // Re-enable all services
        enableAllServices();

        // Reset all booking data
        resetAllBookingData();

        // Clear service selection
        currentService = null;

        // Remove visual selection from service cards
        document.querySelectorAll('.service-card').forEach(card => {
            card.classList.remove('selected');
            card.style.borderColor = 'transparent';
            card.style.backgroundColor = '';
            // Remove any selection badges
            const badge = card.querySelector('.position-absolute');
            if (badge) badge.remove();
        });

        // Remove visual selection from location cards
        document.querySelectorAll('.location-card').forEach(card => {
            card.classList.remove('selected');
            card.style.borderColor = 'transparent';
            // Remove any selection badges
            const badge = card.querySelector('.position-absolute');
            if (badge) badge.remove();
        });

        // Hide all sections except service selection
        const locationSection = document.getElementById('locationSelectionSection');
        if (locationSection) locationSection.style.display = 'none';

        const calendarSection = document.getElementById('calendarMainSection');
        if (calendarSection) calendarSection.style.display = 'none';

        const addressSection = document.getElementById('addressSection');
        if (addressSection) addressSection.style.display = 'none';

        // Reset form inputs
        const serviceInput = document.getElementById('currentServiceInput');
        if (serviceInput) serviceInput.value = '';

        const locationSelect = document.getElementById('locationSelect');
        if (locationSelect) locationSelect.value = '';

        const dateInput = document.getElementById('currentDateInput');
        if (dateInput) dateInput.value = '';
    }

    function resetOnPageLoad() {
        // Re-enable all services
        enableAllServices();

        // Reset all global variables
        currentService = null;
        selectedDate = null;
        selectedSlot = null;
        selectedEmployee = null;
        isActiveBookingFlow = false;
        isPackageBooking = false;

        // Reset package-specific variables
        packageServices = {};
        packageBookingData = {};
        packageServicesList = [];
        currentPackageServiceIndex = 0;
        selectedPackageId = null;

        // Clear visual selections
        setTimeout(() => {
            // Remove service card selections
            document.querySelectorAll('.service-card').forEach(card => {
                card.classList.remove('selected');
                card.style.borderColor = 'transparent';
                card.style.backgroundColor = '';
                const badge = card.querySelector('.position-absolute');
                if (badge) badge.remove();
            });

            // Remove location card selections
            document.querySelectorAll('.location-card').forEach(card => {
                card.classList.remove('selected');
                card.style.borderColor = 'transparent';
                const badge = card.querySelector('.position-absolute');
                if (badge) badge.remove();
            });

            // Hide sections except service selection
            const locationSection = document.getElementById('locationSelectionSection');
            if (locationSection) locationSection.style.display = 'none';

            const calendarSection = document.getElementById('calendarMainSection');
            if (calendarSection) calendarSection.style.display = 'none';

            const addressSection = document.getElementById('addressSection');
            if (addressSection) addressSection.style.display = 'none';

            // Reset form inputs
            const serviceInput = document.getElementById('currentServiceInput');
            if (serviceInput) serviceInput.value = '';

            const locationSelect = document.getElementById('locationSelect');
            if (locationSelect) locationSelect.value = '';

            const dateInput = document.getElementById('currentDateInput');
            if (dateInput) dateInput.value = '';

        }, 100); // Small delay to ensure DOM is ready
    }

    function initializeTranslations() {
        // Update static text elements with translations
        const visibleSlotsElement = document.getElementById('visibleSlotsCount');
        if (visibleSlotsElement) {
            visibleSlotsElement.textContent = t('loading_available_slots');
        }

        const clickSlotTextElement = document.getElementById('clickSlotText');
        if (clickSlotTextElement) {
            clickSlotTextElement.textContent = t('click_available_slot');
        }

        // Update page title
        const pageTitle = document.getElementById('pageTitle');
        if (pageTitle) {
            pageTitle.textContent = t('book_your_appointment');
        }

        // Update button texts
        const cancelButtonText = document.getElementById('cancelButtonText');
        if (cancelButtonText) {
            cancelButtonText.textContent = t('cancel');
        }

        const resetAllButtonText = document.getElementById('resetAllButtonText');
        if (resetAllButtonText) {
            resetAllButtonText.textContent = t('reset_all');
        }

        const backToPreviousServiceText = document.getElementById('backToPreviousServiceText');
        if (backToPreviousServiceText) {
            backToPreviousServiceText.textContent = t('back_to_previous_service');
        }

        // Update Add to Cart button text
        const addToCartText = document.getElementById('addToCartText');
        if (addToCartText) {
            addToCartText.textContent = t('add_to_cart');
        }
    }

    document.addEventListener('DOMContentLoaded', function() {

        // Initialize translations for static elements
        initializeTranslations();

        // Reset all selections on page load
        resetOnPageLoad();

        loadDateSlider();
        setupDateSliderEvents();
        initializeAnimations();
        loadCartPreview();

        // Check if we have services pre-loaded from server
        const serviceCards = document.querySelectorAll('.service-card');
        if (serviceCards.length === 0) {
            loadServices();
        }

        // Handle service selection from URL parameters or sessionStorage
        handleInitialServiceSelection();
    });

    function handleInitialServiceSelection() {
        // Check URL parameters first
        const urlParams = new URLSearchParams(window.location.search);
        const serviceIdFromUrl = urlParams.get('service_id');

        // Check sessionStorage
        const selectedServiceFromStorage = sessionStorage.getItem('selectedService');
        let serviceData = null;

        if (selectedServiceFromStorage) {
            serviceData = JSON.parse(selectedServiceFromStorage);
        }

        let targetServiceId = serviceIdFromUrl || (serviceData ? serviceData.id : null);

        // Initialize selectedServiceId for currency lookup
        if (targetServiceId) {
            window.selectedServiceId = parseInt(targetServiceId);

            // Find and select the service card
            const serviceCard = document.querySelector(`[data-service-id="${targetServiceId}"]`);
            if (serviceCard) {
                // Trigger reset first, then select
                resetAllBookingData();

                // Set current service without triggering selectService
                currentService = targetServiceId;

                // Update service card styling
                document.querySelectorAll('.service-card').forEach(card => {
                    card.classList.remove('selected');
                    card.style.borderColor = 'transparent';
                });

                serviceCard.classList.add('selected');
                serviceCard.style.borderColor = '#C76E49';

                // Show location selection
                showLocationSelection();
            }
        } else {
            // No service selected initially
            window.selectedServiceId = null;
        }
    }

    function selectService(cardElement) {
        // Prevent any default behavior
        if (event) {
            event.preventDefault();
            event.stopPropagation();
        }

        // Get service data
        const serviceId = cardElement.getAttribute('data-service-id');
        const isPackageAttr = cardElement.getAttribute('data-is-package');
        const isPackage = isPackageAttr && isPackageAttr !== 'False' && isPackageAttr !== 'false' && isPackageAttr !== '0';

        // Update global selectedServiceId for currency lookup
        window.selectedServiceId = parseInt(serviceId);

        // Check if this service is already selected (toggle functionality)
        const isCurrentlySelected = cardElement.classList.contains('selected');

        if (isCurrentlySelected) {
            // Unselect the service
            cardElement.classList.remove('selected');
            cardElement.style.borderColor = 'transparent';

            // Clear service data
            currentService = null;
            window.selectedServiceId = null;
            isPackageBooking = false;

            // Clear hidden inputs
            const serviceSelect = document.getElementById('serviceSelect');
            if (serviceSelect) serviceSelect.value = '';

            const serviceInput = document.getElementById('currentServiceInput');
            if (serviceInput) serviceInput.value = '';

            // Reset all dependent data and hide sections
            resetAllBookingData();

            // Hide all dependent sections when service is unselected
            const locationSelectionSection = document.getElementById('locationSelectionSection');
            if (locationSelectionSection) locationSelectionSection.style.display = 'none';

            const addressSection = document.getElementById('addressSection');
            if (addressSection) addressSection.style.display = 'none';

            const calendarMainSection = document.getElementById('calendarMainSection');
            if (calendarMainSection) calendarMainSection.style.display = 'none';


            // Package services section removed - no need to hide
            return false;
        }

        // Remove previous selection styling from all cards
        document.querySelectorAll('.service-card').forEach(card => {
            card.classList.remove('selected');
            card.style.borderColor = 'transparent';
        });

        // Add selection styling to clicked card
        cardElement.classList.add('selected');
        cardElement.style.borderColor = '#C76E49';

        // Update hidden select for JavaScript compatibility
        const serviceSelect = document.getElementById('serviceSelect');
        if (serviceSelect) {
            serviceSelect.value = serviceId;
        }

        // Store service info
        currentService = serviceId;
        isPackageBooking = isPackage;

        // Show reset button since a service is now selected
        document.getElementById('resetAllBtn').style.display = 'block';

        // Reset all booking data when service changes
        resetAllBookingData();

        // Store in hidden input for reference
        const serviceInput = document.getElementById('currentServiceInput');
        if (serviceInput) {
            serviceInput.value = serviceId;
        }

        // Handle package vs single service
        if (isPackage) {
            loadPackageServices(serviceId);
        } else {
            // For regular services, make sure all services are enabled
            enableAllServices();
            showLocationSelection();
        }

        return false; // Prevent any navigation
    }

    function selectLocation(cardElement, locationType) {
        // Prevent any default behavior
        if (event) {
            event.preventDefault();
            event.stopPropagation();
        }

        // Check if this location is already selected (toggle functionality)
        const isCurrentlySelected = cardElement.classList.contains('selected');

        if (isCurrentlySelected) {
            // Unselect the location
            cardElement.classList.remove('selected');
            cardElement.style.borderColor = 'transparent';

            // Remove selection badge
            const existingBadge = cardElement.querySelector('.position-absolute');
            if (existingBadge) {
                existingBadge.remove();
            }

            // Clear location data
            const locationSelect = document.getElementById('locationSelect');
            if (locationSelect) locationSelect.value = '';

            // Reset dependent data (date and calendar)
            resetAfterLocationChange();

            // Hide calendar section
            const calendarMainSection = document.getElementById('calendarMainSection');
            if (calendarMainSection) calendarMainSection.style.display = 'none';

            // Hide address input if it was shown
            const addressSection = document.getElementById('addressSection');
            if (addressSection) addressSection.style.display = 'none';

            return false;
        }

        // Remove previous selection styling from all cards
        document.querySelectorAll('.location-card').forEach(card => {
            card.classList.remove('selected');
            card.style.borderColor = 'transparent';
            // Remove any existing badges
            const badge = card.querySelector('.position-absolute');
            if (badge) badge.remove();
        });

        // Add selection styling to clicked card
        cardElement.classList.add('selected');
        cardElement.style.borderColor = locationType === 'inside' ? '#C76E49' : '#C76E49';

        // Update hidden select for JavaScript compatibility
        const locationSelect = document.getElementById('locationSelect');
        if (locationSelect) {
            locationSelect.value = locationType;
        }

        // Also set data attribute on the card for reference
        cardElement.setAttribute('data-location', locationType);

        // Clear previous date selection but don't hide sections
        selectedDate = null;
        currentDateOffset = 0;

        // Clear date styling
        const dateCards = document.querySelectorAll('.date-card');
        dateCards.forEach(card => {
            card.classList.remove('selected');
            card.style.borderColor = 'transparent';
        });

        // Reset date input
        const dateInput = document.getElementById('currentDateInput');
        if (dateInput) dateInput.value = '';
        // Clear calendar data but preserve visibility
        currentEmployees = {};
        currentSlots = {};
        selectedSlot = null;
        selectedEmployee = null;
        currentEmployeePage = 0;
        employeeAvailability = {};

        // Set active booking flow flag when location is selected with a service
        if (currentService) {
            isActiveBookingFlow = true;
        }

        // Show visual feedback
        const existingBadge = cardElement.querySelector('.position-absolute');
        if (existingBadge) {
            existingBadge.remove();
        }

        const badge = document.createElement('div');
        badge.className = 'position-absolute';
        badge.style.cssText = 'top: 10px; right: 10px; z-index: 10;';
        badge.innerHTML = '<span class="badge badge-success"><i class="fa fa-check"></i> Selected</span>';
        cardElement.style.position = 'relative';
        cardElement.appendChild(badge);

        // Handle address input visibility
        toggleAddressInput();

        // Show the calendar section now that location is selected
        document.getElementById('calendarMainSection').style.display = 'block';

        // Scroll to calendar section
        document.getElementById('calendarMainSection').scrollIntoView({ behavior: 'smooth', block: 'start' });

        // Update pricing and load calendar if ready
        updatePricing();

        // Load calendar data if service is selected
        if (currentService) {
            loadDateSlider();
            loadEmployeesAndShowCalendar();
        }

        return false; // Prevent any navigation
    }

