    function showPackageServices(packageId) {
        // Show visual feedback that package is selected
        const selectedCard = document.querySelector('.service-card.selected');
        if (selectedCard) {
            const existingBadge = selectedCard.querySelector('.position-absolute');
            if (existingBadge) {
                existingBadge.remove();
            }

            const badge = document.createElement('div');
            badge.className = 'position-absolute';
            badge.style.cssText = 'top: 10px; right: 10px; z-index: 10;';
            badge.innerHTML = '<span class="badge badge-success"><i class="fa fa-check"></i> Selected</span>';
            selectedCard.style.position = 'relative';
            selectedCard.appendChild(badge);
        }

        // Update step header
        const stepHeader = document.querySelector('#serviceSelectionSection .card-header h5');
        if (stepHeader) {
            stepHeader.innerHTML = t('package_selected');
        }

        // Load and show package services
        fetch('/book-appointment/api/package-services', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {
                    package_id: parseInt(packageId)
                },
                id: Date.now()
            })
        })
        .then(response => response.json())
        .then(data => {
            const services = data.result || [];
            displayPackageServices(services);
            // Package services section removed - auto-starts with first service
        })
        .catch(error => {
            // Show location selection as fallback
            showLocationSelection();
        });
    }

