    function loadEmployeesAndShowCalendar() {
        const serviceId = currentService;
        if (!serviceId) return;

        // Check if selected service is a package
        if (isPackageBooking) {
            loadPackageServices(serviceId);
            return;
        }

        // Load employees for service and show calendar directly
        fetch('/book-appointment/api/service-plans', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({service_id: parseInt(serviceId)})
        })
        .then(response => response.json())
        .then(data => {
            const plans = data.result || {};
            currentEmployees = {};

            // Collect all employees from all plans with real branch names and IDs
            Object.values(plans).forEach(plan => {
                if (plan.employees && plan.branch_name) {
                    if (plan.id && !currentBranchId) {
                        currentBranchId = plan.id;
                    }

                    Object.entries(plan.employees).forEach(([empId, empData]) => {
                        currentEmployees[empId] = {
                            ...empData,
                            branch_name: plan.branch_name,
                            branch_id: plan.id || currentBranchId
                        };
                    });
                }
            });

            // If no employees found from service plans, get all appointment employees
            if (Object.keys(currentEmployees).length === 0) {
                fetch('/book-appointment/api/all-employees', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify({})
                })
                .then(response => response.json())
                .then(data => {
                    const employees = data.result || data;
                    currentEmployees = employees;
                    showFilters();
                    populateFilters();
                    updateEmployeeHeaders();
                    document.getElementById('calendarContainer').style.display = 'block';
                    generateSlots();
                })
                .catch(error => {
                    // Fallback to static data
                    currentEmployees = {
                        '2': { name: 'Staff Member 1', branch_name: 'Branch 1', image: false, has_image: false },
                        '3': { name: 'Staff Member 2', branch_name: 'Branch 2', image: false, has_image: false }
                    };
                    showFilters();
                    populateFilters();
                    updateEmployeeHeaders();
                    document.getElementById('calendarContainer').style.display = 'block';
                    generateSlots();

                    // Update step header to show calendar is ready
                    const stepHeader = document.querySelector('.card-header h5');
                    if (stepHeader) {
                        stepHeader.innerHTML = 'Complete - Ready to Book';
                    }
                });
                return;
            }

            // Show calendar directly instead of employee selection
            showFilters();
            populateFilters();
            updateEmployeeHeaders();
            document.getElementById('calendarContainer').style.display = 'block';
            generateSlots();

            // Update step header to show calendar is ready
            const stepHeader = document.querySelector('.card-header h5');
            if (stepHeader) {
                stepHeader.innerHTML = 'Complete - Ready to Book';
            }
        })
        .catch(error => {
            // Fallback handling
            currentEmployees = {
                '2': { name: 'Staff Member 1', branch_name: 'Branch 1', image: false, has_image: false },
                '3': { name: 'Staff Member 2', branch_name: 'Branch 2', image: false, has_image: false }
            };
            showFilters();
            populateFilters();
            updateEmployeeHeaders();
            document.getElementById('calendarContainer').style.display = 'block';
            generateSlots();

            // Update step header to show calendar is ready
            const stepHeader = document.querySelector('.card-header h5');
            if (stepHeader) {
                stepHeader.innerHTML = 'Complete - Ready to Book';
            }
        });
    }

    function loadServices() {
        // Load real appointment services from database
        fetch('/book-appointment/api/all-services', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({})
        })
        .then(response => response.json())
        .then(data => {
            const services = data.result || data;
            const serviceSelect = document.getElementById('serviceSelect');
            serviceSelect.innerHTML = '<option value="">Select Service</option>';

            if (Array.isArray(services) && services.length > 0) {
                services.forEach(service => {
                    const isPackage = service.is_package || service.is_appointment_package;
                    const label = isPackage ? `📦 ${service.name} (Package)` : service.name;
                    serviceSelect.innerHTML += `<option value="${service.id}" data-is-package="${isPackage}">${label}</option>`;
                });
            } else {
                serviceSelect.innerHTML += '<option disabled="disabled">No services available</option>';
            }
        })
        .catch(error => {

            // Fallback: try to get services from service plans
            fetch('/book-appointment/api/service-plans', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({})
            })
            .then(response => response.json())
            .then(data => {
                const plans = data.result || {};
                const serviceSelect = document.getElementById('serviceSelect');
                serviceSelect.innerHTML = '<option value="">Select Service</option>';

                const uniqueServices = new Map();
                Object.values(plans).forEach(plan => {
                    if (plan.service_id && plan.service_name) {
                        uniqueServices.set(plan.service_id, {
                            id: plan.service_id,
                            name: plan.service_name,
                            is_package: false
                        });
                    }
                });

                if (uniqueServices.size > 0) {
                    uniqueServices.forEach(service => {
                        serviceSelect.innerHTML += `<option value="${service.id}">${service.name}</option>`;
                    });
                } else {
                    serviceSelect.innerHTML += '<option disabled="disabled">No services available</option>';
                }
            })
            .catch(fallbackError => {
                const serviceSelect = document.getElementById('serviceSelect');
                serviceSelect.innerHTML = '<option value="">Select Service</option>';
                serviceSelect.innerHTML += '<option disabled="disabled">Error loading services</option>';
            });
        });
    }

    function loadDateSlider() {
        generateDateCards();
    }

    function setupDateSliderEvents() {
        const prevBtn = document.getElementById('prevDateBtn');
        const nextBtn = document.getElementById('nextDateBtn');

        if (prevBtn) {
            prevBtn.addEventListener('click', () => {
                currentDateOffset -= 7;
                generateDateCards();
            });
        }

        if (nextBtn) {
            nextBtn.addEventListener('click', () => {
                currentDateOffset += 7;
                generateDateCards();
            });
        }
    }

    function generateDateCards() {
        const dateCardsContainer = document.getElementById('dateCards');
        dateCardsContainer.innerHTML = '';

        const today = new Date();
        for (let i = 0; i < 7; i++) {
            const date = new Date(today);
            date.setDate(today.getDate() + currentDateOffset + i);
            const dateStr = date.toISOString().split('T')[0];

            const dayName = date.toLocaleDateString('en-US', { weekday: 'short' });
            const dayNum = date.getDate();
            const monthName = date.toLocaleDateString('en-US', { month: 'short' });

            const isSelected = selectedDate === dateStr;
            const isToday = date.toDateString() === today.toDateString();

            const cardHtml = `
                <div class="date-card text-center p-2 rounded cursor-pointer ${isSelected ? 'bg-primary text-white' : 'bg-white border'} ${isToday ? 'border-primary' : ''}" 
                     data-date="${dateStr}" 
                     onclick="selectDate('${dateStr}')"
                     style="min-width: 70px; cursor: pointer; transition: all 0.2s;">
                    <div class="font-weight-bold">${dayName}</div>
                    <div class="h5 mb-0">${dayNum}</div>
                    <div class="small">${monthName}</div>
                    ${isToday ? '<div class="small text-primary font-weight-bold">Today</div>' : ''}
                </div>
            `;
            dateCardsContainer.innerHTML += cardHtml;
        }
    }

    function selectDate(dateStr) {
        // Check if this date is already selected (toggle functionality)
        if (selectedDate === dateStr) {

            // Unselect the date
            selectedDate = null;
            generateDateCards(); // Refresh to clear selection

            // Reset calendar data
            resetCalendarData();

            // Hide calendar container when date is unselected
            const calendarContainer = document.getElementById('calendarContainer');
            if (calendarContainer) calendarContainer.style.display = 'none';

            // Update step header back to date selection
            const stepHeader = document.querySelector('.card-header h5');
            if (stepHeader) {
                stepHeader.innerHTML = 'Select Date, Time & Professional';
            }

            return;
        }

        selectedDate = dateStr;
        generateDateCards(); // Refresh to show selection

        // Don't reset calendar data when selecting a date - preserve sections visibility

        // Only load calendar if service is already selected
        if (currentService) {
            // Update step header to show date is selected
            const stepHeader = document.querySelector('.card-header h5');
            if (stepHeader) {
                stepHeader.innerHTML = 'Service Summary';
            }

            loadEmployeesAndShowCalendar();
        }
    }

    function previousEmployeePage() {
        if (currentEmployeePage > 0) {
            currentEmployeePage--;
            updateEmployeeHeaders();
            renderSlotsTable();
        }
    }

    function nextEmployeePage() {
        const availableEmployees = getAvailableEmployees();
        const maxPages = Math.ceil(availableEmployees.length / employeesPerPage);
        if (currentEmployeePage < maxPages - 1) {
            currentEmployeePage++;
            updateEmployeeHeaders();
            renderSlotsTable();
        }
    }

    function getAvailableEmployees() {
        // Get employees who have slots for the selected date
        const employeesWithSlots = Object.entries(currentEmployees).filter(([empId, emp]) => {
            return currentSlots[empId] && Object.keys(currentSlots[empId]).length > 0;
        });

        if (employeesWithSlots.length === 0) {
            // Return all employees if no slots data yet
            return Object.entries(currentEmployees);
        }

        return employeesWithSlots;
    }

    function updateEmployeePagination() {
        const availableEmployees = getAvailableEmployees();
        const totalEmployees = availableEmployees.length;
        const maxPages = Math.ceil(totalEmployees / employeesPerPage);

        const paginationContainer = document.getElementById('employeePaginationContainer');
        const pageInfo = document.getElementById('employeePageInfo');
        const prevBtn = document.getElementById('prevEmployeeBtn');
        const nextBtn = document.getElementById('nextEmployeeBtn');

        if (totalEmployees <= employeesPerPage) {
            // Hide pagination if 3 or fewer employees
            paginationContainer.style.display = 'none';
        } else {
            paginationContainer.style.display = 'flex';

            const startEmployee = (currentEmployeePage * employeesPerPage) + 1;
            const endEmployee = Math.min((currentEmployeePage + 1) * employeesPerPage, totalEmployees);
            pageInfo.textContent = `Showing ${startEmployee}-${endEmployee} of ${totalEmployees} employees`;

            prevBtn.disabled = currentEmployeePage === 0;
            nextBtn.disabled = currentEmployeePage >= maxPages - 1;
        }
    }

    function loadEmployeesAndShowCalendar() {
        const serviceId = currentService;
        if (!serviceId) return;

        // Check if selected service is a package
        if (isPackageBooking) {
            loadPackageServices(serviceId);
            return;
        }

        // Load employees for service and show calendar directly
        fetch('/book-appointment/api/service-plans', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {
                    service_id: parseInt(serviceId)
                },
                id: Date.now()
            })
        })
        .then(response => response.json())
        .then(data => {
            if (data.result && Object.keys(data.result).length > 0) {
                const plans = data.result;
                currentEmployees = {};

                // Store plans globally for pricing calculations (like booking.js does)
                window.servicePlans = plans;

                // Extract employees from plans
                Object.entries(plans).forEach(([planId, plan]) => {
                    if (plan.employees) {
                        Object.entries(plan.employees).forEach(([empId, empData]) => {
                            currentEmployees[empId] = {
                                ...empData,
                                plan_id: planId
                            };
                        });
                    }
                });

                // Store employees globally for pricing calculations (like booking.js does)
                window.currentEmployees = currentEmployees;

                // Show calendar container
                document.getElementById('calendarContainer').style.display = 'block';

                // Initialize employee pagination
                currentEmployeePage = 0;
                showFilters();
                populateFilters();
                updateEmployeeHeaders();
                updateEmployeeNavigation();

                // Load date slider if not already loaded
                if (!selectedDate) {
                    loadDateSlider();
                }

                // Generate slots for current date
                if (selectedDate) {
                    generateSlots();
                }

            }
        })
        .catch(error => {
            console.error('Error loading service plans:', error);
        });
    }

    function loadPackageServices(packageId) {
        // Store the selected package ID for later use
        selectedPackageId = packageId;

        // Disable all other services when a package is selected
        disableAllServicesExcept(packageId.toString());

        fetch('/book-appointment/api/package-services/' + packageId, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({})
        })
        .then(response => response.json())
        .then(data => {
            const services = data.result || data;

            if (Array.isArray(services) && services.length > 0) {
                // Initialize package data structures
                packageServices = {};
                packageBookingData = {};
                packageServicesList = [];
                currentPackageServiceIndex = 0;

                // Store services data
                services.forEach((service, index) => {
                    packageServices[service.id] = service;
                    packageBookingData[service.id] = null;
                    packageServicesList.push(service);
                });

                // Auto-start with the first service
                startPackageServiceBooking(0);

            } else {
                showMessage(t('no_services_in_package'), 'error');
            }
        })
        .catch(error => {
            showMessage(t('error_loading_package_services'), 'error');
        });
    }

    function startPackageServiceBooking(serviceIndex) {
        currentPackageServiceIndex = serviceIndex;
        const service = packageServicesList[serviceIndex];

        // Set current service for booking
        currentService = service.id;
        isPackageBooking = false; // Allow normal booking flow

        // Reset location and calendar data for new service (each service needs fresh location selection)
        resetLocationData();
        resetDateData();
        resetCalendarData();

        // Hide calendar section until location is selected
        const calendarSection = document.getElementById('calendarMainSection');
        if (calendarSection) calendarSection.style.display = 'none';

        // Update page title to show progress
        const pageTitle = document.querySelector('h1, .page-title');
        if (pageTitle) {
            pageTitle.innerHTML = `
                <div class="text-center">
                    <div>📦 ${t('package_service_number')} ${serviceIndex + 1} ${t('of')} ${packageServicesList.length}</div>
                    <div>
                        <span class="badge text-white px-3 py-2 fs-5" style="background: linear-gradient(135deg, #C76E49 0%, #A85B3D 100%) !important;">${service.name}</span>
                    </div>
                </div>
            `;
        }

        // Show location selection first (employees will be loaded after location is selected)
        showLocationSelection();

        // Update navigation buttons
        updatePrimaryActionButton();
    }

    function goToNextPackageService() {
        if (currentPackageServiceIndex < packageServicesList.length - 1) {
            startPackageServiceBooking(currentPackageServiceIndex + 1);
        }
    }

    function goToPreviousPackageService() {
        if (currentPackageServiceIndex > 0) {
            startPackageServiceBooking(currentPackageServiceIndex - 1);
        }
    }

    function bookPackageService(serviceId) {
        // This function is now replaced by startPackageServiceBooking
        // Set current service for booking
        currentService = serviceId;
        isPackageBooking = false; // Temporarily treat as single service for booking flow

        // Hide package section and show calendar

        // Load employees for this specific service
        loadEmployeesForService(serviceId);
    }

    function loadEmployeesForService(serviceId) {
        // Get service plans to find employees
        fetch('/book-appointment/api/service-plans', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({service_id: parseInt(serviceId)})
        })
        .then(response => response.json())
        .then(data => {
            const plans = data.result || {};
            currentEmployees = {};

            // Collect all employees from all plans with real branch names and IDs
            Object.values(plans).forEach(plan => {
                if (plan.employees && plan.branch_name) {
                    // Update current branch ID from the first plan
                    if (plan.id && !currentBranchId) {
                        currentBranchId = plan.id;
                    }

                    // Ensure each employee gets the correct branch name from the plan
                    Object.entries(plan.employees).forEach(([empId, empData]) => {
                        currentEmployees[empId] = {
                            ...empData,
                            branch_name: plan.branch_name,
                            branch_id: plan.id || currentBranchId
                        };
                    });
                }
            });

            // Show calendar for service booking
            document.getElementById('calendarContainer').style.display = 'none'; // Hide initially
            updateEmployeeHeaders();
            if (selectedDate) {
                generateSlots();
            }
        })
        .catch(error => {
            console.error('Error loading service employees:', error);
        });
    }

    function proceedWithPackageBooking() {
        const allBooked = Object.values(packageBookingData).every(data => data !== null);

        if (allBooked) {
            // Add complete package to cart
            addPackageToCart();
        } else {
            // Show message about incomplete booking
            const incompleteServices = Object.keys(packageServices).filter(serviceId => 
                packageBookingData[serviceId] === null
            ).map(serviceId => packageServices[serviceId].name);

            showMessage(`Please complete booking for: ${incompleteServices.join(', ')}`, 'warning');
        }
    }

    function loadEmployees() {
        const serviceSelect = document.getElementById('serviceSelect');
        const serviceId = serviceSelect.value;
        if (!serviceId) {
            document.getElementById('calendarContainer').style.display = 'none';
                return;
        }

        currentService = serviceId;

        // Check if selected service is a package
        const selectedOption = serviceSelect.options[serviceSelect.selectedIndex];
        isPackageBooking = selectedOption.getAttribute('data-is-package') === 'true';

        if (isPackageBooking) {
            loadPackageServices(serviceId);
            return;
        }

        // Get service plans to find employees with real branch data
        fetch('/book-appointment/api/service-plans', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({service_id: parseInt(serviceId)})
        })
        .then(response => response.json())
        .then(data => {
            const plans = data.result || {};
            currentEmployees = {};

            // Collect all employees from all plans with real branch names and IDs
            Object.values(plans).forEach(plan => {
                if (plan.employees && plan.branch_name) {
                    // Update current branch ID from the first plan (or could be made selectable)
                    if (plan.id && !currentBranchId) {
                        currentBranchId = plan.id;
                    }

                    // Ensure each employee gets the correct branch name from the plan
                    Object.entries(plan.employees).forEach(([empId, empData]) => {
                        currentEmployees[empId] = {
                            ...empData,
                            branch_name: plan.branch_name, // Use dynamic branch name from plan
                            branch_id: plan.id || currentBranchId // Store branch ID for API calls
                        };
                    });
                }
            });

            // If no employees found from service plans, get all appointment employees with images
            if (Object.keys(currentEmployees).length === 0) {
                fetch('/book-appointment/api/all-employees', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify({})
                })
                .then(response => response.json())
                .then(data => {
                    const employees = data.result || data;
                    currentEmployees = employees;
                    updateEmployeeHeaders();
                    generateSlots();
                })
                .catch(error => {
                    // Use basic fallback structure with dynamic loading
                    fetch('/book-appointment/api/all-employees', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({})
                    })
                    .then(response => response.json())
                    .then(fallbackData => {
                        currentEmployees = fallbackData.result || fallbackData;
                        updateEmployeeHeaders();
                        generateSlots();
                    })
                    .catch(() => {
                        // Final fallback if all APIs fail
                        currentEmployees = {
                            '2': { name: 'Staff Member 1', branch_name: 'Branch 1', image: false, has_image: false },
                            '3': { name: 'Staff Member 2', branch_name: 'Branch 2', image: false, has_image: false }
                        };
                        updateEmployeeHeaders();
                        generateSlots();
                    });
                });
                return; // Exit early to wait for API response
            }

            updateEmployeeHeaders();
            generateSlots();
        })
        .catch(error => {
            // Load all employees with images as fallback
            fetch('/book-appointment/api/all-employees', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({})
            })
            .then(response => response.json())
            .then(data => {
                const employees = data.result || data;
                currentEmployees = employees;
                updateEmployeeHeaders();
                generateSlots();
            })
            .catch(fallbackError => {
                // Get branch names dynamically using branches API
                fetch('/book-appointment/api/branches', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({})
                })
                .then(response => response.json())
                .then(branchData => {
                    const branches = branchData.result || branchData;
                    const branchNames = Object.values(branches);

                    // Basic fallback with dynamic branch names
                    currentEmployees = {
                        '2': {
                            name: 'Staff Member 1',
                            branch_name: branchNames[0] || 'Branch 1',
                            image: false,
                            has_image: false
                        },
                        '3': {
                            name: 'Staff Member 2',
                            branch_name: branchNames[1] || 'Branch 2',
                            image: false,
                            has_image: false
                        }
                    };
                    updateEmployeeHeaders();
                    generateSlots();
                })
                .catch(() => {
                    // Final static fallback
                    currentEmployees = {
                        '2': { name: 'Staff Member 1', branch_name: 'Branch 1', image: false, has_image: false },
                        '3': { name: 'Staff Member 2', branch_name: 'Branch 2', image: false, has_image: false }
                    };
                    updateEmployeeHeaders();
                    generateSlots();
                });
            });
        });
    }


    function updateEmployeeHeaders() {
        const employeeHeaderElement = document.querySelector('#employeeHeaders');
        if (!employeeHeaderElement) {
            return;
        }

        // Clear only the employee headers content, keep the Time column
        employeeHeaderElement.innerHTML = `<i class="fa fa-users text-warning"></i> ${t('available_professionals')}`;

        // Get available employees and apply pagination
        const availableEmployees = getAvailableEmployees();
        const startIndex = currentEmployeePage * employeesPerPage;
        const endIndex = startIndex + employeesPerPage;
        const displayedEmployees = availableEmployees.slice(startIndex, endIndex);

        // Find the header row and remove old employee headers (keep Time column)
        const headerRow = employeeHeaderElement.parentElement;
        const allHeaders = headerRow.querySelectorAll('th');
        for (let i = allHeaders.length - 1; i > 0; i--) {
            // Remove all headers except the first one (Time column)
            allHeaders[i].remove();
        }

        displayedEmployees.forEach(([empId, emp]) => {
            const branchName = emp.branch_name || 'Main Branch';
            const empHeader = document.createElement('th');
            empHeader.className = 'text-center';

            let headerHtml = '';

            // Add employee image if available
            if (emp.has_image && emp.image) {
                headerHtml += `<div class="employee-photo mb-2">
                    <img src="${emp.image}" alt="${emp.name}" 
                         class="rounded-circle" 
                         style="width: 50px; height: 50px; object-fit: cover; border: 2px solid #C76E49;" />
                </div>`;
            } else {
                // Default avatar if no image
                headerHtml += `<div class="employee-photo mb-2">
                    <div class="rounded-circle d-flex align-items-center justify-content-center" 
                         style="width: 50px; height: 50px; background-color: #6c757d; color: white; font-weight: bold; border: 2px solid #C76E49;">
                        ${emp.name.charAt(0).toUpperCase()}
                    </div>
                </div>`;
            }

            headerHtml += `<div class="employee-info">
                <strong>${emp.name}</strong><br/>
                <small class="text-muted">${branchName}</small>
            </div>`;

            empHeader.innerHTML = headerHtml;
            headerRow.appendChild(empHeader);
        });

        // Update pagination controls
        updateEmployeePagination();
    }

    function generateSlots() {
        const serviceId = document.getElementById('serviceSelect').value;

        if (!serviceId || !selectedDate || Object.keys(currentEmployees).length === 0) {
            document.getElementById('calendarContainer').style.display = 'none';
            return;
        }

        showFilters();
        // Only populate filters if they haven't been populated yet (prevent refresh)
        const employeeFilter = document.getElementById('employeeFilter');
        if (employeeFilter && employeeFilter.options.length <= 1) {
            populateFilters();
        }
        document.getElementById('calendarContainer').style.display = 'block';
        const tbody = document.getElementById('slotsTable');
        const columnCount = Object.keys(currentEmployees).length + 1;
        tbody.innerHTML = '<tr><td colspan="' + columnCount + '">Loading slots...</td></tr>';

        // Load real slots for each employee
        const employeeIds = Object.keys(currentEmployees);
        const slotPromises = employeeIds.map(empId => {
            return fetch('/book-appointment/api/slots', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    jsonrpc: '2.0',
                    method: 'call',
                    params: {
                        service_id: parseInt(serviceId),
                        employee_id: parseInt(empId),
                        date: selectedDate,
                        appointment_type: document.getElementById('locationSelect').value,
                        branch_id: currentEmployees[empId]?.branch_id || currentBranchId
                    },
                    id: Date.now()
                })
            })
            .then(response => response.json())
            .then(data => ({employee_id: empId, slots: data.result || {}}))
            .catch(error => {
                return {employee_id: empId, slots: {}};
            });
        });

        Promise.all(slotPromises)
        .then(results => {
            currentSlots = {};
            let hasAnySlots = false;

            results.forEach(result => {
                currentSlots[result.employee_id] = result.slots;
                if (Object.keys(result.slots).length > 0) {
                    hasAnySlots = true;
                }
            });

            // If no slots found from API, generate demo slots
            if (!hasAnySlots) {
                generateDemoSlots();
            }

            renderSlotsTable();

            // Populate filters after slots are loaded with only available employees
            // populateFiltersWithAvailableEmployees(); // Disabled - keeps all options available
        })
        .catch(error => {
            // Generate demo slots as fallback
            generateDemoSlots();
            renderSlotsTable();

        });
    }

    function generateDemoSlots() {
        // Generate time slots from 00:00 to 23:30 with 30-minute intervals
        const timeSlots = [];
        for (let hour = 0; hour < 24; hour++) {
            for (let minute = 0; minute < 60; minute += 30) {
                const timeStr = `${hour.toString().padStart(2, '0')}:${minute.toString().padStart(2, '0')}`;
                timeSlots.push(timeStr);
            }
        }

        currentSlots = {};
        Object.keys(currentEmployees).forEach(empId => {
            currentSlots[empId] = {};
            timeSlots.forEach(time => {
                // Randomly make some slots available (70% chance)
                if (Math.random() > 0.3) {
                    currentSlots[empId][time] = {
                        name: time,
                        id: Math.floor(Math.random() * 1000),
                        ids: [Math.floor(Math.random() * 1000)],
                        employee_id: empId,
                        time: time,
                        duration: 60,
                        state: 'draft'
                    };
                }
            });
        });
    }

    function renderSlotsTable() {
        const tbody = document.getElementById('slotsTable');
        tbody.innerHTML = '';

        // Get all unique time slots
        const allTimes = new Set();
        Object.values(currentSlots).forEach(employeeSlots => {
            Object.keys(employeeSlots).forEach(time => allTimes.add(time));
        });

        const sortedTimes = Array.from(allTimes).sort();

        if (sortedTimes.length === 0) {
            const availableEmployees = getAvailableEmployees();
            const startIndex = currentEmployeePage * employeesPerPage;
            const endIndex = startIndex + employeesPerPage;
            const displayedEmployees = availableEmployees.slice(startIndex, endIndex);
            const columnCount = displayedEmployees.length + 1;
            tbody.innerHTML = `<tr><td colspan="${columnCount}">${t('no_available_slots_date')}</td></tr>`;
            return;
        }

        sortedTimes.forEach(time => {
            const row = document.createElement('tr');

            // Time column
            const timeCell = document.createElement('td');
            timeCell.textContent = time;
            timeCell.className = 'table-secondary text-center font-weight-bold';
            timeCell.style.cssText = 'width: 80px; min-width: 80px; max-width: 100px; vertical-align: middle;';
            row.appendChild(timeCell);

            // Employee columns - only for displayed employees on current page
            const availableEmployees = getAvailableEmployees();
            const startIndex = currentEmployeePage * employeesPerPage;
            const endIndex = startIndex + employeesPerPage;
            const displayedEmployees = availableEmployees.slice(startIndex, endIndex);

            displayedEmployees.forEach(([empId, emp]) => {
                const cell = document.createElement('td');
                cell.className = 'p-1';
                cell.style.cssText = 'width: 200px; min-width: 180px; max-width: 220px; vertical-align: top;';
                const employeeSlots = currentSlots[empId] || {};

                if (employeeSlots[time]) {
                    // Calculate end time
                    const duration = employeeSlots[time].duration || 60;
                    const endTime = calculateEndTime(time, duration);

                    // Get price
                    const location = document.getElementById('locationSelect').value;
                    let price = 0.0; // Dynamic pricing from plan_ids
                    if (location === 'outside') price = 0.0;

                    // Create enhanced slot button with appointment details
                    const slotBtn = document.createElement('button');
                    slotBtn.className = 'btn btn-outline-success slot-btn w-100 text-left';
                    slotBtn.style.cssText = 'height: auto; min-height: 80px; padding: 8px; border-radius: 8px; transition: all 0.2s ease;';

                    slotBtn.innerHTML = `
                        <div class="slot-content">
                            <div class="slot-time text-center mb-1">
                                <strong class="text-primary">${time} - ${endTime}</strong>
                                <span class="badge badge-success badge-sm ml-1">${t('available')}</span>
                            </div>
                            <div class="slot-employee d-flex align-items-center justify-content-center mb-1">
                                ${emp.has_image ? 
                                    `<img src="${emp.image}" class="rounded-circle mr-1" style="width: 16px; height: 16px; object-fit: cover;" alt="${emp.name}"/>` :
                                    `<div class="rounded-circle mr-1 d-flex align-items-center justify-content-center" style="width: 16px; height: 16px; background-color: #6c757d; color: white; font-size: 0.6rem;">${emp.name.charAt(0)}</div>`
                                }
                                <small class="font-weight-bold">${emp.name}</small>
                            </div>
                            <div class="slot-details text-center">
                                <small class="text-muted d-block">${emp.branch_name || 'Main Branch'}</small>
                                <small class="text-success font-weight-bold">${window.getSafeCurrency(window.selectedServiceId)}${price.toFixed(2)} - ${location === 'inside' ? 'At Branch' : 'At Your Location'}</small>
                            </div>
                        </div>
                    `;

                    // Add click event to select slot
                    slotBtn.onclick = function(e) {
                        e.preventDefault();
                        selectSlot(time, empId, employeeSlots[time]);
                    };

                    // Add hover effects
                    slotBtn.addEventListener('mouseenter', function() {
                        this.style.backgroundColor = '#e8f5e8';
                        this.style.borderColor = '#C76E49';
                        this.style.transform = 'scale(1.02)';
                    });

                    slotBtn.addEventListener('mouseleave', function() {
                        this.style.backgroundColor = '';
                        this.style.borderColor = '#C76E49';
                        this.style.transform = 'scale(1)';
                    });

                    cell.appendChild(slotBtn);
                } else {
                    // Create disabled slot for not available
                    const disabledSlot = document.createElement('div');
                    disabledSlot.className = 'text-center text-muted p-3';
                    disabledSlot.style.cssText = 'border: 1px dashed #ddd; border-radius: 8px; background-color: #f8f9fa;';
                    disabledSlot.innerHTML = `<i class="fa fa-times-circle text-muted"></i><br/><small>${t('not_available')}</small>`;
                    cell.appendChild(disabledSlot);
                }

                row.appendChild(cell);
            });

            tbody.appendChild(row);
        });
    }

    function calculateEndTime(startTime, durationMinutes) {
        const [hours, minutes] = startTime.split(':').map(Number);
        const startMinutes = hours * 60 + minutes;
        const endMinutes = startMinutes + (durationMinutes || 60);
        const endHours = Math.floor(endMinutes / 60);
        const endMins = endMinutes % 60;
        return `${endHours.toString().padStart(2, '0')}:${endMins.toString().padStart(2, '0')}`;
    }

    function selectSlot(time, employeeId, slotData) {
        // Clear previous selections
        document.querySelectorAll('.slot-btn.selected').forEach(btn => {
            btn.classList.remove('selected');
        });

        // Find and select the clicked slot button
        const clickedSlot = event ? event.target.closest('.slot-btn') : null;
        if (clickedSlot) {
            clickedSlot.classList.add('selected');
        }

        const employee = currentEmployees[employeeId];
        const location = document.getElementById('locationSelect').value;

        // Get real price from backend
        fetch('/book-appointment/api/price', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                service_id: parseInt(currentService),
                branch_id: currentEmployees[employeeId]?.branch_id || currentBranchId,
                employee_id: parseInt(employeeId),
                appointment_type: location
            })
        })
        .then(response => response.json())
        .then(data => {
            const price = data.result || (location === 'outside' ? 75 : 50); // fallback pricing

            // Update booking summary table
            const serviceName = document.querySelector('.service-card.selected h5')?.textContent || 'Selected Service';
            updateBookingSummaryTable({
                service: serviceName,
                date: new Date(selectedDate).toLocaleDateString(),
                time: time + ' - ' + calculateEndTime(time, 60),
                employee: employee.name,
                branch: employee.branch_name || 'Main Branch',
                location: location === 'inside' ? 'At Branch' : 'At Your Location',
                price: window.getSafeCurrency(window.selectedServiceId) + price.toFixed(2)
            });

            document.getElementById('selectedSlot').style.display = 'block';
            document.getElementById('emptySlot').style.display = 'none';

            selectedSlot = {
                time: time,
                employee_id: employeeId,
                employee_name: employee.name,
                slot_data: slotData,
                price: price,
                date: selectedDate,
                location: location,
                service_id: currentService
            };
        })
        .catch(error => {
            // Use fallback pricing
            const price = location === 'outside' ? 75 : 50;

            let detailsHtml = 
                '<strong>Date:</strong> ' + new Date(selectedDate).toLocaleDateString() + '<br/>' +
                '<strong>Time:</strong> ' + time + '<br/>' +
                '<strong>Employee:</strong> ' + employee.name + '<br/>' +
                '<strong>Branch:</strong> ' + (employee.branch_name || 'Main Branch') + '<br/>' +
                '<strong>Location:</strong> ' + (location === 'inside' ? 'At Branch' : 'At Your Location') + '<br/>';

            // Add address info if 'at your location' is selected
            if (location === 'outside') {
                const address = document.getElementById('customerAddress').value.trim();
                const city = document.getElementById('customerCity').value.trim();
                if (address && city) {
                    detailsHtml += '<strong>Service Address:</strong> ' + address + ', ' + city + '<br/>';
                }
            }

            detailsHtml += '<strong>Price:</strong> ' + window.getSafeCurrency(window.selectedServiceId) + price.toFixed(2);

            const details = document.getElementById('slotDetails');
            details.innerHTML = detailsHtml;

            document.getElementById('selectedSlot').style.display = 'block';
            document.getElementById('emptySlot').style.display = 'none';

            selectedSlot = {
                time: time,
                employee_id: employeeId,
                employee_name: employee.name,
                slot_data: slotData,
                price: price,
                date: selectedDate,
                location: location,
                service_id: currentService
            };
        });
    }

    function updateBookingSummaryTable(details) {
        // Update each row with provided details
        if (details.service) {
            document.getElementById('serviceInfo').textContent = details.service;
            document.getElementById('serviceRow').style.display = 'table-row';
        }

        if (details.date) {
            document.getElementById('dateInfo').textContent = details.date;
            document.getElementById('dateRow').style.display = 'table-row';
        }

        if (details.time) {
            document.getElementById('timeInfo').textContent = details.time;
            document.getElementById('timeRow').style.display = 'table-row';
        }

        if (details.employee) {
            document.getElementById('employeeInfo').textContent = details.employee;
            document.getElementById('employeeRow').style.display = 'table-row';
        }

        if (details.branch) {
            document.getElementById('branchInfo').textContent = details.branch;
            document.getElementById('branchRow').style.display = 'table-row';
        }

        if (details.location) {
            document.getElementById('locationInfo').textContent = details.location;
            document.getElementById('locationRow').style.display = 'table-row';
        }

        if (details.price) {
            document.getElementById('priceInfo').textContent = details.price;
            document.getElementById('priceRow').style.display = 'table-row';
        }

        // Add animation to table
        const table = document.getElementById('bookingSummaryTable');
        table.style.animation = 'slideInUp 0.6s ease-out';

        // Update primary action button based on context
        updatePrimaryActionButton();
    }

    function clearBookingSummaryTable() {
        // Hide all rows
        ['serviceRow', 'dateRow', 'timeRow', 'employeeRow', 'branchRow', 'locationRow', 'priceRow'].forEach(rowId => {
            document.getElementById(rowId).style.display = 'none';
        });
    }

    function addToCart() {
        if (!selectedSlot) return;


        // Validate address input if 'at your location' is selected
        if (!validateAddressInput()) {
            return;
        }

        // Show loading screen
        showLoadingScreen('جاري إضافة الخدمة...');

        // Prepare appointment data for cart
        const employee = currentEmployees[selectedSlot.employee_id];
        const resolvedSlotIds = selectedSlot.slot_data?.ids || (selectedSlot.slot_data?.id ? [selectedSlot.slot_data.id] : []);
        const appointmentData = {
            service_id: parseInt(currentService),
            employee_id: parseInt(selectedSlot.employee_id),
            employee_name: selectedSlot.employee_name,
            date: selectedSlot.date,
            time: selectedSlot.time,
            display_time: selectedSlot.time,
            price: selectedSlot.price,
            location: selectedSlot.location,
            slot_ids: resolvedSlotIds,
            appointment_type: selectedSlot.location,
            branch_id: employee?.branch_id || currentBranchId,
            branch_name: employee?.branch_name || 'Main Branch',
            service_name: document.querySelector('.service-card.selected h5')?.textContent || 'Selected Service'
        };


        // Add address data if 'at your location' is selected
        if (selectedSlot.location === 'outside') {
            appointmentData.customer_street = document.getElementById('customerAddress').value.trim();
            appointmentData.customer_city = document.getElementById('customerCity').value.trim();
            appointmentData.customer_phone = document.getElementById('customerPhone').value.trim();
            appointmentData.customer_notes = document.getElementById('customerNotes').value.trim();
        }

        // Check if this is part of a package booking
        if (Object.keys(packageServices).length > 0 && packageServices[selectedSlot.service_id]) {
            // Show loading screen for package service
            showLoadingScreen(t('booking_package_service'));

            // Store package service booking data
            packageBookingData[selectedSlot.service_id] = appointmentData;

            // Show success message and return to package view
            const successDiv = document.createElement('div');
            successDiv.className = 'alert alert-success mt-2';
            successDiv.innerHTML = '<i class="fa fa-check-circle"></i> Service booked! Returning to package overview...';
            // Find the right container for the message
            const summaryContainer = document.querySelector('#selectedSlot .p-3') || document.getElementById('selectedSlot');
            if (summaryContainer) {
                summaryContainer.appendChild(successDiv);
            }

            // Service booking status update removed - using streamlined workflow

            setTimeout(() => {
                // Hide loading screen after package service is booked
                hideLoadingScreen();

                document.getElementById('calendarContainer').style.display = 'none';
            }, 2000);

            return;
        }


        // Regular single service booking
        fetch('/appointment/cart/add', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {
                    appointment_data: appointmentData
                },
                id: Date.now()
            })
        })
        .then(response => {
            if (!response.ok) {
                throw new Error(`HTTP ${response.status}: ${response.statusText}`);
            }
            return response.json();
        })
        .then(data => {

            // Handle JSON-RPC response format
            let result = data;
            if (data && data.result) {
                result = data.result;
            }

            // Check for JSON-RPC errors first
            if (data && data.error) {
                throw new Error(data.error.message || 'Server error');
            }

            // Check for success in multiple possible response formats
            const isSuccess = result && (
                result.success === true || 
                result.status === 'success' ||
                (result.cart_quantity !== undefined && result.cart_url)
            );

            if (isSuccess) {
                // Hide loading screen
                hideLoadingScreen();

                // Update cart badge if cart_quantity is provided
                if (result.cart_quantity !== undefined) {
                    updateCartBadge(result.cart_quantity);
                }

                // Show success animation
                showSuccessAnimation();

                // Show success message in booking summary
                const successDiv = document.createElement('div');
                successDiv.className = 'alert alert-success mt-2 animate-slide-up';
                successDiv.innerHTML = '<i class="fa fa-check-circle"></i> Appointment added to cart successfully!<br/><small>Redirecting to cart...</small>';
                // Find the right container for the message
            const summaryContainer = document.querySelector('#selectedSlot .p-3') || document.getElementById('selectedSlot');
            if (summaryContainer) {
                summaryContainer.appendChild(successDiv);
            }

                // Mark slot as booked with animation
                document.querySelectorAll('.btn-success').forEach(btn => {
                    btn.innerHTML = '<i class="fa fa-check"></i> Added';
                    btn.disabled = true;
                    btn.classList.remove('btn-success', 'animate-pulse');
                    btn.classList.add('btn-info');
                    btn.style.transform = 'scale(1.1)';
                    setTimeout(() => {
                        btn.style.transform = 'scale(1)';
                    }, 200);
                });

                // Update cart preview
                updateCartPreview((result.cart_quantity || 1));
                document.getElementById('cartPreview').style.display = 'block';

                // Reset selection after delay
                setTimeout(() => {
                    document.getElementById('selectedSlot').style.display = 'none';
                    document.getElementById('emptySlot').style.display = 'block';
                    selectedSlot = null;
                    showMessage(t('appointment_added_cart'), 'success');

                    // Re-enable all services after successful appointment addition
                    enableAllServices();

                    // Reset all booking data and service selection after successful cart addition
                    resetAfterCartSuccess();

                    // Show payment and back to categories buttons
                    document.getElementById('proceedPaymentBtn').style.display = 'block';
                    document.getElementById('backToCategoriesBtn').style.display = 'block';
                }, 2000);
            } else {
                // Hide loading screen
                hideLoadingScreen();

                // Better error message extraction
                let errorMsg = 'Failed to add to cart';

                if (result && typeof result === 'object') {
                    if (result.error) {
                        errorMsg = typeof result.error === 'string' ? result.error : JSON.stringify(result.error);
                    } else if (result.message) {
                        errorMsg = result.message;
                    } else if (result.detail) {
                        errorMsg = result.detail;
                    } else {
                        // Don't show [object Object], show a meaningful message
                        errorMsg = 'Server returned an error response. Please try again.';
                    }
                } else if (typeof result === 'string') {
                    errorMsg = result;
                }


                // Show error message in booking summary
                const errorDiv = document.createElement('div');
                errorDiv.className = 'alert alert-danger mt-2';
                errorDiv.innerHTML = '<i class="fa fa-exclamation-triangle"></i> ' + errorMsg;

                // Find the right container for the error message
                const summaryContainer = document.querySelector('#selectedSlot .p-3') || document.getElementById('selectedSlot');
                if (summaryContainer) {
                    summaryContainer.appendChild(errorDiv);
                }

                // Auto-hide error after 8 seconds
                setTimeout(() => {
                    if (errorDiv && errorDiv.parentNode) {
                        errorDiv.remove();
                    }
                }, 8000);
            }
        })
        .catch(error => {
            // Hide loading screen
            hideLoadingScreen();

            // Show network error message in booking summary
            const errorDiv = document.createElement('div');
            errorDiv.className = 'alert alert-danger mt-2';

            let errorMessage = 'Network error occurred while adding to cart';
            if (error.message) {
                if (error.message.includes('HTTP')) {
                    errorMessage = 'Server error: ' + error.message;
                } else if (error.message.includes('JSON')) {
                    errorMessage = 'Invalid response from server. Please try again.';
                } else {
                    errorMessage = 'Error: ' + error.message;
                }
            }

            errorDiv.innerHTML = '<i class="fa fa-wifi"></i> ' + errorMessage;

            // Find the right container for the error message
            const summaryContainer = document.querySelector('#selectedSlot .p-3') || document.getElementById('selectedSlot');
            if (summaryContainer) {
                summaryContainer.appendChild(errorDiv);
            }

            // Auto-hide error after 8 seconds
            setTimeout(() => {
                if (errorDiv && errorDiv.parentNode) {
                    errorDiv.remove();
                }
            }, 8000);
        });
    }

    function cancelSlot() {
        // Safely hide elements with null checks
        const selectedSlotEl = document.getElementById('selectedSlot');
        if (selectedSlotEl) {
            selectedSlotEl.style.display = 'none';
        }

        const emptySlotEl = document.getElementById('emptySlot');
        if (emptySlotEl) {
            emptySlotEl.style.display = 'block';
        }

        // Clear booking summary table
        if (typeof clearBookingSummaryTable === 'function') {
            clearBookingSummaryTable();
        }

        // Clear slot button selections
        document.querySelectorAll('.slot-btn.selected').forEach(btn => {
            btn.classList.remove('selected');
        });

        // Reset package mode data
        if (isPackageBooking || Object.keys(packageServices).length > 0) {
            isPackageBooking = false;
            packageServices = {};
            packageBookingData = {};
            packageServicesList = [];
            currentPackageServiceIndex = 0;
            currentService = null;

            // Reset UI to normal booking mode
            const pageTitle = document.querySelector('h1, .page-title');
            if (pageTitle) {
                pageTitle.innerHTML = '<i class="fa fa-calendar-check"></i> ' + t('book_your_appointment');
            }

            // Hide any package-specific UI elements with null checks
            const calendarContainer = document.getElementById('calendarContainer');
            if (calendarContainer) {
                calendarContainer.style.display = 'none';
            }

            // Show main booking interface with null checks
            const servicesContainer = document.getElementById('servicesContainer');
            if (servicesContainer) {
                servicesContainer.style.display = 'block';
            }

            const employeesContainer = document.getElementById('employeesContainer');
            if (employeesContainer) {
                employeesContainer.style.display = 'none';
            }

            // Clear service selections
            document.querySelectorAll('.service-card.selected').forEach(card => {
                card.classList.remove('selected');
            });

        }

        selectedSlot = null;
    }

    function toggleAddressInput() {
        const locationValue = document.getElementById('locationSelect').value;
        const addressSection = document.getElementById('addressSection');

        if (locationValue === 'outside') {
            addressSection.style.display = 'block';
            // Add required validation
            document.getElementById('customerAddress').setAttribute('required', 'required');
            document.getElementById('customerCity').setAttribute('required', 'required');
            document.getElementById('customerPhone').setAttribute('required', 'required');
        } else {
            addressSection.style.display = 'none';
            // Remove required validation
            document.getElementById('customerAddress').removeAttribute('required');
            document.getElementById('customerCity').removeAttribute('required');
            document.getElementById('customerPhone').removeAttribute('required');
        }

        // Update pricing and load calendar if ready
        updatePricing();

        // Load calendar if both service and date are selected
        if (currentService && selectedDate) {
            loadEmployeesAndShowCalendar();
        }
    }

    function updatePricing() {
        // Only regenerate slots if calendar is already visible
        if (currentService && selectedDate && document.getElementById('calendarContainer').style.display !== 'none') {
            generateSlots();
        }
    }

    function addPackageToCart() {
        // Show loading screen for complete package booking
        showLoadingScreen('جاري إضافة الباقة للسلة...');

        const packageData = {
            service_id: parseInt(selectedPackageId), // Package ID
            is_package: true,
            package_services: packageBookingData,
            total_price: 0 // Will be calculated in backend
        };

        // Calculate total price from all services
        Object.values(packageBookingData).forEach(serviceData => {
            packageData.total_price += serviceData.price || 0;
        });

        fetch('/appointment/cart/add', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {
                    appointment_data: packageData
                },
                id: Date.now()
            })
        })
        .then(response => response.json())
        .then(data => {
            const result = data.result || data;

            if (result && (result.success || result.status === 'success')) {
                // Hide loading screen on success with minimum display time
                setTimeout(() => {
                    hideLoadingScreen();
                }, 1500);

                // Update cart badge if cart_quantity is provided
                if (result.cart_quantity !== undefined) {
                    updateCartBadge(result.cart_quantity);
                }

                // Show success message  
                showMessage(t('package_added_cart'), 'success');

                // Re-enable all services after successful package addition
                enableAllServices();

                // Clear all package appointment data
                packageServices = {};
                packageBookingData = {};
                packageServicesList = [];
                currentPackageServiceIndex = 0;
                selectedPackageId = null;
                isPackageBooking = false;

                // Clear all booking data  
                resetAllBookingData();

                // Reset service selection
                currentService = null;
                selectedSlot = null;

                // Reset all service selections and UI
                resetAfterCartSuccess();

                // Get current category ID from URL
                const urlParams = new URLSearchParams(window.location.search);
                const categoryId = urlParams.get('category_id') || '';

                // Redirect to calendar with same category after short delay
                setTimeout(() => {
                    const redirectUrl = `/appointment/booking/calendar${categoryId ? '?category_id=' + categoryId : ''}`;
                    window.location.href = redirectUrl;
                }, 1500);
            } else {
                // Hide loading screen on error
                hideLoadingScreen();

                const errorMsg = result.error || result.message || 'Failed to add package to cart';
                showMessage(t('error') + ' ' + errorMsg, 'error');
            }
        })
        .catch(error => {
            // Hide loading screen on network error
            hideLoadingScreen();

            showMessage(t('network_error') + ' ' + error.message, 'error');
        });
    }

    function initializeAnimations() {
        // Add staggered animations to cards
        const cards = document.querySelectorAll('.card');
        cards.forEach((card, index) => {
            setTimeout(() => {
                card.classList.add('animate-fade-in');
            }, index * 100);
        });

        // Add hover effects to buttons
        const buttons = document.querySelectorAll('.btn');
        buttons.forEach(button => {
            button.addEventListener('mouseenter', function() {
                this.style.transform = 'translateY(-2px) scale(1.02)';
            });

            button.addEventListener('mouseleave', function() {
                this.style.transform = 'translateY(0) scale(1)';
            });
        });

        // Add loading animations
        const loadingElements = document.querySelectorAll('[data-loading]');
        loadingElements.forEach(element => {
            element.classList.add('loading-shimmer');
        });
    }

    function loadCartPreview() {
        // Check if user has items in cart and show preview
        fetch('/shop/cart', {
            method: 'GET',
            headers: {
                'Content-Type': 'application/json',
            }
        })
        .then(response => response.text())
        .then(html => {
            // Parse cart quantity from response
            const cartQtyMatch = html.match(/cart.*?quantity.*?(\d+)/i);
            if (cartQtyMatch && parseInt(cartQtyMatch[1]) > 0) {
                document.getElementById('cartPreview').style.display = 'block';
                updateCartPreview(parseInt(cartQtyMatch[1]));
            }
        })
    }

    function updateCartPreview(quantity) {
        // Add animation
        const cartPreview = document.getElementById('cartPreview');
        cartPreview.classList.add('animate-slide-up');
    }

    function showSuccessAnimation() {
        // Create a success animation overlay
        const overlay = document.createElement('div');
        overlay.style.cssText = `
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(40, 167, 69, 0.9);
            z-index: 9999;
            display: flex;
            justify-content: center;
            align-items: center;
            animation: fadeIn 0.3s ease-in-out;
        `;

        overlay.innerHTML = `
            <div class="text-center text-white animate-slide-up">
                <i class="fa fa-check-circle fa-5x mb-3"></i>
                <h2>Success!</h2>
                <p>Your appointment has been added to cart</p>
                <div class="spinner-border mt-3" role="status">
                    <span class="sr-only">Redirecting...</span>
                </div>
            </div>
        `;

        document.body.appendChild(overlay);

        setTimeout(() => {
            overlay.remove();
        }, 2000);
    }

    function addLoadingState(element, text = 'Loading...') {
        element.disabled = true;
        element.innerHTML = `<i class="fa fa-spinner fa-spin"></i> ${text}`;
        element.classList.add('loading-shimmer');
    }

    function removeLoadingState(element, originalText, icon = '') {
        element.disabled = false;
        element.innerHTML = `${icon} ${originalText}`;
        element.classList.remove('loading-shimmer');
    }

    function validateAddressInput() {
        const locationValue = document.getElementById('locationSelect').value;
        if (locationValue === 'outside') {
            const address = document.getElementById('customerAddress').value.trim();
            const city = document.getElementById('customerCity').value.trim();
            const phone = document.getElementById('customerPhone').value.trim();

            if (!address || !city || !phone) {
                const errorDiv = document.createElement('div');
                errorDiv.className = 'alert alert-warning mt-2';
                errorDiv.innerHTML = '<i class="fa fa-exclamation-triangle"></i> Please fill in all required address fields.';
                // Find the right container for the error message
                const summaryContainer = document.querySelector('#selectedSlot .p-3') || document.getElementById('selectedSlot');
                if (summaryContainer) {
                    summaryContainer.appendChild(errorDiv);
                }

                setTimeout(() => {
                    errorDiv.remove();
                }, 3000);

                return false;
            }
        }
        return true;
    }

    // Employee pagination functions
    function nextEmployeePage() {
        const totalEmployees = Object.keys(currentEmployees).length;
        const totalPages = Math.ceil(totalEmployees / employeesPerPage);

        if (currentEmployeePage < totalPages - 1) {
            currentEmployeePage++;
            employeeAvailability = {};
            employeeSlotData = {};
            updateEmployeeHeaders();
            updateEmployeeNavigation();
            generateSlots(); // Regenerate slots for new employee page
        }
    }

    function previousEmployeePage() {
        if (currentEmployeePage > 0) {
            currentEmployeePage--;
            employeeAvailability = {};
            employeeSlotData = {};
            updateEmployeeHeaders();
            updateEmployeeNavigation();
            generateSlots(); // Regenerate slots for new employee page
        }
    }


    function updateEmployeeHeaders() {
        const totalEmployees = Object.keys(currentEmployees).length;
        const startIndex = currentEmployeePage * employeesPerPage;
        const endIndex = Math.min(startIndex + employeesPerPage, totalEmployees);
        const employeeEntries = Object.entries(currentEmployees);
        const currentPageEmployees = employeeEntries.slice(startIndex, endIndex);

        // Update the calendar header row
        const headerRow = document.getElementById('calendarHeader');
        if (headerRow) {
            // Clear existing employee headers (keep time column)
            const timeColumn = headerRow.querySelector('.time-column');
            headerRow.innerHTML = '';
            headerRow.appendChild(timeColumn);

            // Add employee columns
            currentPageEmployees.forEach(([empId, empData]) => {
                const th = document.createElement('th');
                th.className = 'py-3 text-center employee-column';
                th.setAttribute('data-employee-id', empId);
                th.setAttribute('data-employee-hidden', 'false');

                let headerContent = '<div class="text-white">';

                // Add employee image if available, otherwise larger icon
                if (empData.has_image && empData.image) {
                    headerContent += `<div class="employee-photo mb-2">
                        <img src="${empData.image}" alt="${empData.name}" 
                             class="rounded-circle" 
                             style="width: 40px; height: 40px; object-fit: cover; border: 2px solid #ffffff;" />
                    </div>`;
                } else {
                    // Larger icon when no employee image
                    headerContent += `<div class="mb-2">
                        <i class="fa fa-user fa-2x"></i>
                    </div>`;
                }

                headerContent += `<small>${empData.name}</small></div>`;

                th.innerHTML = headerContent;
                headerRow.appendChild(th);
            });
        }

        // Generate time slots after headers are updated
        generateTimeSlots(currentPageEmployees);
    }

    function updateEmployeeNavigation() {
        const totalEmployees = Object.keys(currentEmployees).length;
        const totalPages = Math.ceil(totalEmployees / employeesPerPage);
        const container = document.getElementById('employeePaginationContainer');
        const prevBtn = document.getElementById('prevEmployeeBtn');
        const nextBtn = document.getElementById('nextEmployeeBtn');
        const pageInfo = document.getElementById('employeePageInfo');

        if (totalPages > 1) {
            container.style.display = 'flex';
            prevBtn.disabled = currentEmployeePage === 0;
            nextBtn.disabled = currentEmployeePage >= totalPages - 1;

            const startEmp = (currentEmployeePage * employeesPerPage) + 1;
            const endEmp = Math.min((currentEmployeePage + 1) * employeesPerPage, totalEmployees);
            pageInfo.textContent = `${startEmp}-${endEmp} of ${totalEmployees} professionals`;
        } else {
            container.style.display = 'none';
        }
    }

    function generateSlots() {
        // This should trigger the existing slot generation logic
        if (currentEmployees && selectedDate) {
            employeeAvailability = {};
            employeeSlotData = {};
            // Load slots for the selected date
            loadSlotsForDate(selectedDate);
            // Show filters when slots are regenerated (but don't repopulate to preserve selections)
            // Only show filters if they're not already visible to prevent refresh
            const appointmentFilters = document.getElementById('appointmentFilters');
            if (appointmentFilters && appointmentFilters.style.display !== 'block') {
                showFilters();
            }

            // Update package slot states if this is package booking
            if (isPackageBooking) {
                // Add delay to ensure slots are rendered first
                setTimeout(() => {
                    updatePackageSlotStates();
                }, 500);
            }
        }
    }

    // Generate 30 days with slider functionality
    let currentSlideIndex = 0;
    let totalDates = 30;
    let visibleDates = 7;
    let allDates = [];

    function loadDateSlider() {
        const dateCards = document.getElementById('dateCards');
        if (!dateCards) return;

        const today = new Date();
        allDates = [];
        let dateCardsHtml = '';

        // Generate 30 days (today + 29 days)
        for (let i = 0; i < totalDates; i++) {
            const currentDate = new Date(today);
            currentDate.setDate(today.getDate() + i);

            const dateStr = currentDate.toISOString().split('T')[0];
            const dayName = currentDate.toLocaleDateString('en-US', { weekday: 'short' });
            const dayNumber = currentDate.getDate();
            const monthName = currentDate.toLocaleDateString('en-US', { month: 'short' });

            allDates.push({
                dateStr, dayName, dayNumber, monthName,
                isToday: i === 0
            });

            const isToday = i === 0;
            const cardClass = isToday ? 'selected' : '';

            dateCardsHtml += `
                <div class="col-auto" style="min-width: 110px;margin: 5px;">
                    <div class="card date-card ${cardClass}" data-date="${dateStr}" onclick="selectDate('${dateStr}', this)" style="cursor: pointer; transition: all 0.3s;">
                        <div class="card-body text-center py-3">
                            <div class="font-weight-bold">${dayName}</div>
                            <div class="h5 mb-0">${dayNumber}</div>
                            <div class="small text-muted">${monthName}</div>
                        </div>
                    </div>
                </div>
            `;
        }

        dateCards.innerHTML = dateCardsHtml;
        updateDateRangeText();
        updateSliderButtons();

        // Auto-select today
        if (!selectedDate) {
            selectedDate = today.toISOString().split('T')[0];
        }
    }

    function slideDates(direction) {
        const maxSlide = Math.max(0, totalDates - visibleDates);
        currentSlideIndex = Math.max(0, Math.min(maxSlide, currentSlideIndex + direction));

        const dateCards = document.getElementById('dateCards');
        const slideAmount = currentSlideIndex * (110 + 15); // card width + gap
        dateCards.style.transform = `translateX(-${slideAmount}px)`;

        updateDateRangeText();
        updateSliderButtons();
    }

    function updateDateRangeText() {
        const rangeText = document.getElementById('dateRangeText');
        if (!rangeText || allDates.length === 0) return;

        const startIndex = currentSlideIndex;
        const endIndex = Math.min(startIndex + visibleDates - 1, allDates.length - 1);

        if (startIndex === endIndex) {
            rangeText.textContent = `${allDates[startIndex].monthName} ${allDates[startIndex].dayNumber}`;
        } else {
            const startDate = allDates[startIndex];
            const endDate = allDates[endIndex];

            if (startDate.monthName === endDate.monthName) {
                rangeText.textContent = `${startDate.monthName} ${startDate.dayNumber} - ${endDate.dayNumber}`;
            } else {
                rangeText.textContent = `${startDate.monthName} ${startDate.dayNumber} - ${endDate.monthName} ${endDate.dayNumber}`;
            }
        }
    }

    function updateSliderButtons() {
        const prevBtn = document.getElementById('prevWeek');
        const nextBtn = document.getElementById('nextWeek');

        if (prevBtn) prevBtn.disabled = currentSlideIndex === 0;
        if (nextBtn) nextBtn.disabled = currentSlideIndex >= totalDates - visibleDates;
    }

    function selectDate(dateStr, element) {
        // Remove previous selection
        document.querySelectorAll('.date-card').forEach(card => {
            card.classList.remove('selected');
        });

        // Add selection to clicked card
        element.classList.add('selected');
        selectedDate = dateStr;

        employeeAvailability = {};
        employeeSlotData = {};

        // Regenerate calendar for new date
        if (currentEmployees && Object.keys(currentEmployees).length > 0) {
            loadSlotsForDate(dateStr);
            // Show filters after date selection (same pattern as location selection)
            showFilters();
            // Only populate filters if they're empty (preserve existing selections)
            const employeeFilter = document.getElementById('employeeFilter');
            if (employeeFilter && employeeFilter.options.length <= 1) {
                populateFilters();
            }
        }

    }

    function generateTimeSlots(currentPageEmployees) {
        const slotsTable = document.getElementById('slotsTable');
        if (!slotsTable || !selectedDate) return;

        // Clear existing slots
        slotsTable.innerHTML = '';

        // Generate time slots for full day (00:00 to 23:30) with 30-minute intervals
        for (let hour = 0; hour < 24; hour++) {
            for (let minute = 0; minute < 60; minute += 30) {
                const timeStr = `${hour.toString().padStart(2, '0')}:${minute.toString().padStart(2, '0')}`;
                const row = document.createElement('tr');
                row.className = 'slot-row';
                row.style.display = 'none'; // Initially hidden until availability is loaded
                row.setAttribute('data-hidden', 'true');

                // Time column
                const timeCell = document.createElement('td');
                timeCell.className = 'time-cell py-2 font-weight-bold';
                timeCell.textContent = timeStr;
                row.appendChild(timeCell);

                // Employee slot columns
                currentPageEmployees.forEach(([empId, empData]) => {
                    const slotCell = document.createElement('td');
                    slotCell.className = 'slot-cell text-center py-1';
                    slotCell.setAttribute('data-employee-id', empId);
                    slotCell.setAttribute('data-time', timeStr);
                    slotCell.innerHTML = `
                        <button class="btn btn-outline-secondary btn-sm slot-btn" 
                                onclick="bookAppointment('${empId}', '${timeStr}')"
                                style="min-width: 80px; font-size: 0.75rem; padding: 0.25rem 0.5rem;"
                                data-available="false" data-employee-hidden="false" disabled>
                            Loading...
                        </button>
                    `;
                    slotCell.setAttribute('data-employee-hidden', 'false');
                    row.appendChild(slotCell);
                });

                slotsTable.appendChild(row);
            }
        }

        // Load actual slot availability
        loadSlotsForDate(selectedDate);
    }

    function loadSlotsForDate(date) {
        const totalEmployees = Object.keys(currentEmployees).length;
        const startIndex = currentEmployeePage * employeesPerPage;
        const endIndex = Math.min(startIndex + employeesPerPage, totalEmployees);
        const employeeEntries = Object.entries(currentEmployees);
        const currentPageEmployees = employeeEntries.slice(startIndex, endIndex);

        currentPageEmployees.forEach(([empId, empData]) => {
            // Load actual slots for this employee and date
            loadEmployeeSlots(empId, empData, date);
        });
    }

    function loadEmployeeSlots(employeeId, employeeData, date) {
        // Make API call to get actual slot availability
        fetch('/book-appointment/api/slots', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {
                    service_id: parseInt(currentService),
                    employee_id: parseInt(employeeId),
                    date: date,
                    appointment_type: document.getElementById('locationSelect')?.value || 'inside',
                    branch_id: employeeData.branch_id || 1
                },
                id: Date.now()
            })
        })
        .then(response => response.json())
        .then(data => {
            if (data.result) {
                updateEmployeeSlots(employeeId, data.result);
            }
        })
    }

    function updateEmployeeSlots(employeeId, slots) {
        // Track availability for this employee
        let hasAnyAvailableSlots = false;

        // Store full slot data for multi-slot booking lookup
        employeeSlotData[employeeId] = slots;

        // Update the slot buttons for this employee with actual availability
        const employeeCells = document.querySelectorAll(`[data-employee-id="${employeeId}"]`);

        employeeCells.forEach(cell => {
            if (cell.className.includes('slot-cell')) {
                const time = cell.getAttribute('data-time');
                const button = cell.querySelector('.slot-btn');

                if (button) {
                    // Check if this time slot is available
                    const isAvailable = checkSlotAvailability(slots, time);

                    if (isAvailable) {
                        button.className = 'btn btn-success btn-sm slot-btn';
                        button.textContent = t('available');
                        button.disabled = false;
                        button.setAttribute('data-available', 'true');
                        hasAnyAvailableSlots = true;
                    } else {
                        button.className = 'btn btn-secondary btn-sm slot-btn';
                        button.textContent = t('unavailable');
                        button.disabled = true;
                        button.setAttribute('data-available', 'false');
                    }
                }
            }
        });

        // Store employee availability status
        employeeAvailability[employeeId] = hasAnyAvailableSlots;

        // After updating this employee's slots, check which employees and time slots should be hidden
        hideUnavailableEmployeesAndTimeSlots();
    }

    function checkSlotAvailability(slots, time) {
        // Check if the time slot exists in the available slots
        if (Array.isArray(slots)) {
            return slots.some(slot => slot.time === time);
        } else if (typeof slots === 'object') {
            return Object.keys(slots).includes(time);
        }
        return false;
    }

    function updatePackageSlotStates() {
        // Update slot button states to show conflicts in package booking
        if (!isPackageBooking || packageUsedSlots.size === 0) return;

        // Get all slot buttons
        const slotButtons = document.querySelectorAll('.slot-btn');

        slotButtons.forEach(button => {
            const cell = button.closest('.slot-cell');
            if (!cell) return;

            const employeeId = cell.getAttribute('data-employee-id');
            const time = cell.getAttribute('data-time');
            const slotKey = `${employeeId}-${selectedDate}-${time}`;

            if (packageUsedSlots.has(slotKey)) {
                // This slot is already used in package - mark as unavailable
                button.className = 'btn btn-warning btn-sm slot-btn';
                button.textContent = t('used_in_package');
                button.disabled = true;
                button.setAttribute('data-package-used', 'true');
            } else if (button.getAttribute('data-package-used') === 'true') {
                // This slot was previously marked as used but is now available again
                // Restore its original state (check if it's actually available)
                const isAvailable = button.getAttribute('data-available') === 'true';
                if (isAvailable) {
                    button.className = 'btn btn-success btn-sm slot-btn';
                    button.textContent = t('available');
                    button.disabled = false;
                } else {
                    button.className = 'btn btn-secondary btn-sm slot-btn';
                    button.textContent = t('unavailable');
                    button.disabled = true;
                }
                button.removeAttribute('data-package-used');
            }
        });
    }

    // Add debounce mechanism to prevent multiple calls
    let isBookingInProgress = false;

    function bookAppointment(employeeId, time) {

        // Prevent multiple simultaneous calls
        if (isBookingInProgress) {
            return;
        }

        isBookingInProgress = true;

        if (!currentService || !selectedDate) {
            showMessage(t('select_service_date_first'), 'error');
            isBookingInProgress = false;
            return;
        }

        // Get location type from stored location selection
        let locationType = 'inside';
        const locationSelect = document.getElementById('locationSelect');
        if (locationSelect) {
            locationType = locationSelect.value;
        } else {
            // Try to get from selected location card
            const selectedLocationCard = document.querySelector('.location-card.selected');
            if (selectedLocationCard) {
                locationType = selectedLocationCard.getAttribute('data-location') || 'inside';
            }
        }

        // Convert time format for database lookup
        // Frontend time "08:00" -> database time 8.0
        let dbTime = parseFloat(time.split(':')[0]) + parseFloat(time.split(':')[1]) / 60;

        // Look up slot data from API response for this employee+time
        let slotData = null;
        const empSlots = employeeSlotData[employeeId];
        if (empSlots && typeof empSlots === 'object') {
            if (empSlots[time]) {
                slotData = empSlots[time];
            } else {
                // Try matching by slot name
                Object.values(empSlots).forEach(s => {
                    if (s.name === time) slotData = s;
                });
                if (slotData) {
                } else {
                }
            }
        } else {
        }

        const appointmentData = {
            service_id: parseInt(currentService),
            employee_id: parseInt(employeeId),
            date: selectedDate,
            time: time,
            appointment_type: locationType,
            slot_ids: slotData ? (slotData.ids || [slotData.id]) : [],
            branch_id: 1
        };

        // Show loading feedback
        const button = event.target;
        const originalText = button.textContent;
        button.textContent = 'Booking...';
        button.disabled = true;

        // Reset button immediately
        button.textContent = originalText;
        button.disabled = false;

        // Just populate the summary without adding to cart

        // Get employee data
        const employee = currentEmployees[employeeId];
        const serviceName = document.querySelector('.service-card.selected h5')?.textContent || 'Selected Service';

        // Update booking summary table
        updateBookingSummaryTable({
            service: serviceName,
            date: new Date(selectedDate).toLocaleDateString(),
            time: time + ' - ' + calculateEndTime(time, 60),
            employee: employee?.name || 'Selected Professional',
            branch: employee?.branch_name || 'Main Branch',
            location: locationType === 'inside' ? 'At Branch' : 'At Your Location',
            price: window.getSafeCurrency(window.selectedServiceId) + '0.00' // Dynamic price, will be updated via price API
        });

        // Store selected slot data
        selectedSlot = {
            time: time,
            employee_id: employeeId,
            employee_name: employee?.name || 'Selected Professional',
            slot_data: slotData,
            price: 0.0,
            date: selectedDate,
            location: locationType,
            service_id: currentService,
            id: slotData ? slotData.id : null
        };

        selectedEmployee = {
            id: employeeId,
            name: employee?.name || 'Selected Professional'
        };

        // Show the summary section
        document.getElementById('selectedSlot').style.display = 'block';
        document.getElementById('emptySlot').style.display = 'none';

        // Calculate price dynamically from loaded plan data
        let dynamicPrice = 0.0;

        // Get employee data from the properly loaded currentEmployees
        const empData = window.currentEmployees && window.currentEmployees[employeeId];

        if (window.servicePlans && empData && empData.plan_id) {
            const plan = window.servicePlans[empData.plan_id];

            if (plan) {
                dynamicPrice = locationType === 'inside' ? 
                    (plan.price_inside || 0.0) : 
                    (plan.price_outside || 0.0);
            }
        }

        selectedSlot.price = dynamicPrice;

        // Update price in summary
        const priceInfo = document.getElementById('priceInfo');
        if (priceInfo) {
            priceInfo.textContent = window.getSafeCurrency(window.selectedServiceId) + dynamicPrice.toFixed(2);
        }

        // Package service booking is now handled by handlePackageServiceAction()
        // This bookAppointment function only handles the slot selection display

        // Reset flag at end of regular booking flow
        isBookingInProgress = false;
    }

