    function hideUnavailableEmployeesAndTimeSlots() {
        // First, check if all employees have been processed
        const totalEmployees = Object.keys(currentEmployees).length;
        const startIndex = currentEmployeePage * employeesPerPage;
        const endIndex = Math.min(startIndex + employeesPerPage, totalEmployees);
        const currentPageEmployees = Object.entries(currentEmployees).slice(startIndex, endIndex);

        // Check if all employees on current page have been processed
        let allEmployeesProcessed = true;
        currentPageEmployees.forEach(([empId, empData]) => {
            if (!(empId in employeeAvailability)) {
                allEmployeesProcessed = false;
            }
        });

        if (!allEmployeesProcessed) {
            return; // Wait for all employees to be processed
        }

        // Hide columns for employees with no available slots
        hideUnavailableEmployeeColumns();

        // Hide time slot rows that have no available employees
        hideUnavailableTimeSlotRows();

        // Update the visible slots count info
        updateVisibleSlotsInfo();
    }

    function hideUnavailableEmployeeColumns() {
        // Get employee headers and check availability
        const employeeHeaders = document.querySelectorAll('.employee-column');

        employeeHeaders.forEach(header => {
            const employeeId = header.getAttribute('data-employee-id');
            const hasAvailableSlots = employeeAvailability[employeeId];

            if (hasAvailableSlots === false) {
                // Hide the header column
                header.style.display = 'none';
                header.setAttribute('data-employee-hidden', 'true');

                // Hide all slot cells for this employee
                const employeeCells = document.querySelectorAll(`[data-employee-id="${employeeId}"].slot-cell`);
                employeeCells.forEach(cell => {
                    cell.style.display = 'none';
                    cell.setAttribute('data-employee-hidden', 'true');
                });
            } else {
                // Show the header column
                header.style.display = '';
                header.setAttribute('data-employee-hidden', 'false');

                // Show all slot cells for this employee
                const employeeCells = document.querySelectorAll(`[data-employee-id="${employeeId}"].slot-cell`);
                employeeCells.forEach(cell => {
                    cell.style.display = '';
                    cell.setAttribute('data-employee-hidden', 'false');
                });
            }
        });
    }

    function hideUnavailableTimeSlotRows() {
        // Get all time slot rows
        const slotRows = document.querySelectorAll('.slot-row');

        slotRows.forEach(row => {
            const timeCell = row.querySelector('.time-cell');
            if (!timeCell) return;

            // Check if any VISIBLE employee has this time slot available
            const visibleButtons = row.querySelectorAll('.slot-btn[data-employee-hidden="false"]');
            let hasAvailableSlot = false;
            let allButtonsLoaded = true;

            visibleButtons.forEach(button => {
                if (button.getAttribute('data-available') === 'true') {
                    hasAvailableSlot = true;
                }
                if (button.textContent === 'Loading...') {
                    allButtonsLoaded = false;
                }
            });

            // Only make decision if all buttons have been loaded with data
            if (allButtonsLoaded && visibleButtons.length > 0) {
                if (hasAvailableSlot) {
                    // Show the row if at least one visible employee is available
                    row.style.display = '';
                    row.setAttribute('data-hidden', 'false');
                } else {
                    // Hide the row if no visible employees are available
                    row.style.display = 'none';
                    row.setAttribute('data-hidden', 'true');
                }
            } else if (visibleButtons.length === 0) {
                // Hide row if no visible employees at all
                row.style.display = 'none';
                row.setAttribute('data-hidden', 'true');
            }
        });
    }

    function updateVisibleSlotsInfo() {
        const totalRows = document.querySelectorAll('.slot-row').length;
        const hiddenRows = document.querySelectorAll('.slot-row[data-hidden="true"]').length;
        const visibleRows = totalRows - hiddenRows;

        const totalEmployees = document.querySelectorAll('.employee-column').length;
        const hiddenEmployees = document.querySelectorAll('.employee-column[data-employee-hidden="true"]').length;
        const visibleEmployees = totalEmployees - hiddenEmployees;

        // Update the UI with availability info
        const visibleSlotsElement = document.getElementById('visibleSlotsCount');
        if (visibleSlotsElement) {
            if (visibleRows === 0 || visibleEmployees === 0) {
                visibleSlotsElement.innerHTML = '<span class="text-warning">No available appointments for selected date</span>';
            } else {
                visibleSlotsElement.innerHTML = `<span class="text-success">${visibleEmployees} professionals • ${visibleRows} time slots available</span>`;
            }
        }

    }

