    function handlePrimaryAction() {
        // Determine what action to take based on current context
        if (Object.keys(packageServices).length > 0) {
            // This is a package booking - handle package flow
            handlePackageServiceAction();
        } else {
            // Regular service booking - add to cart
            addToSummaryCart();
        }
    }

    function handlePackageServiceAction() {

        // TEST: Show loading screen immediately to test if it works
        showLoadingScreen('جاري الاختبار...');

        // First, store the current package service data
        if (!selectedSlot || !currentService) {
            hideLoadingScreen(); // Hide on error
            showMessage(t('select_time_slot_first'), 'error');
            return;
        }

        // Show loading screen for package service booking
        showLoadingScreen(t('booking_package_service'));

        // Check for slot conflicts in package booking
        const slotKey = `${selectedSlot.employee_id}-${selectedSlot.date}-${selectedSlot.time}`;
        if (packageUsedSlots.has(slotKey)) {
            hideLoadingScreen(); // Hide loading screen on error
            showMessage(t('slot_already_selected'), 'error');
            return;
        }

        // Add slot to used slots set
        packageUsedSlots.add(slotKey);

        // Update UI to show this slot as used
        updatePackageSlotStates();

        // Get employee data for the current service
        const employee = currentEmployees[selectedSlot.employee_id];
        const locationType = document.getElementById('locationSelect')?.value || 'inside';

        // Create appointment data for this package service
        const appointmentData = {
            service_id: parseInt(currentService),
            employee_id: parseInt(selectedSlot.employee_id),
            employee_name: selectedSlot.employee_name || employee?.name || 'Selected Professional',
            date: selectedSlot.date || selectedDate,
            time: selectedSlot.time,
            display_time: selectedSlot.time,
            price: selectedSlot.price || 0,
            location: locationType,
            slot_ids: selectedSlot.slot_data?.ids || [selectedSlot.slot_data?.id] || [],
            appointment_type: locationType,
            branch_id: employee?.branch_id || 1,
            branch_name: employee?.branch_name || 'Main Branch',
            service_name: packageServices[currentService]?.name || t('package_service')
        };

        // Store package service booking data
        packageBookingData[currentService] = appointmentData;


        // Check if this is the last service in the package
        const totalServices = Object.keys(packageServices).length;
        const bookedServices = Object.keys(packageBookingData).filter(serviceId => packageBookingData[serviceId] !== null).length;
        const isLastService = bookedServices >= totalServices;

        if (isLastService) {
            // Last service - add complete package to cart

            // Hide loading screen before proceeding to final package submission with minimum display time
            setTimeout(() => {
                hideLoadingScreen();
                proceedWithPackageBooking();
            }, 1000);
        } else {
            // Not last service - automatically go to next service

            // Show success popup message
            showMessage(t('service_booked_next'), 'success');

            // Hide loading screen after showing success message with minimum display time
            setTimeout(() => {
                hideLoadingScreen();
            }, 1500);

            // Auto-proceed to next service after 2 seconds
            setTimeout(() => {
                goToNextPackageService();
            }, 2000);
        }
    }

    function updatePrimaryActionButton() {
        const btn = document.getElementById('primaryActionBtn');
        const backBtn = document.getElementById('packageBackBtn');
        if (!btn) return;

        if (Object.keys(packageServices).length > 0 && packageServicesList.length > 0) {
            // This is a package booking - use index-based logic
            const isLastService = currentPackageServiceIndex >= packageServicesList.length - 1;
            const isFirstService = currentPackageServiceIndex <= 0;
            const currentServiceName = packageServicesList[currentPackageServiceIndex]?.name || 'Service';

            // Update primary action button
            if (isLastService) {
                btn.innerHTML = '<i class="fa fa-check-circle"></i> إكمال الباقة وإضافة للسلة';
                btn.className = 'btn btn-success btn-block mb-2';
            } else {
                const nextServiceName = packageServicesList[currentPackageServiceIndex + 1]?.name || t('next_service');
                btn.innerHTML = `<i class="fa fa-arrow-right"></i> ${t('proceed_to')} ${nextServiceName}`;
                btn.className = 'btn btn-primary btn-block mb-2';
            }

            // Update back button visibility
            if (backBtn) {
                if (isFirstService) {
                    backBtn.style.display = 'none';
                } else {
                    const prevServiceName = packageServicesList[currentPackageServiceIndex - 1]?.name || 'الخدمة السابقة';
                    backBtn.innerHTML = `<i class="fa fa-arrow-left"></i> العودة إلى ${prevServiceName}`;
                    backBtn.style.display = 'block';
                }
            }
        } else {
            // Regular service booking
            btn.innerHTML = '<i class="fa fa-plus-circle"></i> ' + t('add_to_cart');
            btn.className = 'btn btn-primary btn-block mb-2';

            // Hide back button for regular services
            if (backBtn) {
                backBtn.style.display = 'none';
            }
        }
    }

    function addToSummaryCart() {

        if (!selectedSlot || !currentService || !selectedDate || !selectedEmployee) {
            showMessage(t('select_required_info'), 'error');
            return;
        }

        // Show loading screen
        showLoadingScreen('جاري إضافة الخدمة...');

        // Prevent double-clicking
        const addToCartBtn = document.querySelector('button[onclick="addToSummaryCart()"]');
        if (addToCartBtn && addToCartBtn.disabled) {
            return;
        }

        // Disable button during API call
        if (addToCartBtn) {
            addToCartBtn.disabled = true;
            addToCartBtn.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Adding...';
        }

        // Create booking data in the same format as working addToCart function
        const employee = currentEmployees[selectedSlot.employee_id] || selectedEmployee;
        const resolvedSlotIds = selectedSlot.slot_data?.ids || (selectedSlot.id ? [selectedSlot.id] : []);
        const appointmentData = {
            service_id: parseInt(currentService),
            employee_id: parseInt(selectedEmployee.id),
            employee_name: selectedEmployee.name,
            date: selectedDate,
            time: selectedSlot.time,
            display_time: selectedSlot.time,
            price: selectedSlot.price,
            location: document.getElementById('locationSelect')?.value || 'inside',
            slot_ids: resolvedSlotIds,
            appointment_type: document.getElementById('locationSelect')?.value || 'inside',
            branch_id: employee?.branch_id || 1,
            branch_name: employee?.branch_name || 'Main Branch',
            service_name: document.querySelector('.service-card.selected h5')?.textContent || 'Selected Service'
        };



        // Add address data if 'at your location' is selected
        const locationType = document.getElementById('locationSelect')?.value || 'inside';
        if (locationType === 'outside') {
            appointmentData.customer_street = document.getElementById('customerAddress')?.value || '';
            appointmentData.customer_city = document.getElementById('customerCity')?.value || '';
            appointmentData.customer_phone = document.getElementById('customerPhone')?.value || '';
            appointmentData.customer_notes = document.getElementById('customerNotes')?.value || '';
        }

        // Add to cart via API using the working endpoint
        fetch('/appointment/cart/add', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {
                    appointment_data: appointmentData
                },
                id: Date.now()
            })
        })
        .then(response => {
            if (!response.ok) {
                throw new Error(`HTTP ${response.status}: ${response.statusText}`);
            }
            return response.json();
        })
        .then(data => {
            // Handle JSON-RPC response format
            let result = data;
            if (data && data.result !== undefined) {
                result = data.result;
            }

            // Check for JSON-RPC errors first
            if (data && data.error) {
                const errorMsg = typeof data.error === 'string' ? data.error : (data.error.message || JSON.stringify(data.error));
                throw new Error(errorMsg || 'Server error');
            }

            // Check for errors in the result
            if (result && result.error) {
                const errorMsg = typeof result.error === 'string' ? result.error : JSON.stringify(result.error);
                throw new Error(errorMsg || 'Server error');
            }

            // Check for success in the response with more flexible detection
            const isSuccess = result && (
                result.success === true || 
                result.status === 'success' ||
                (result.cart_quantity !== undefined && result.cart_url) ||
                (result.order_id !== undefined && result.cart_quantity !== undefined) ||
                (result.appointment_id !== undefined && !result.error)
            );

            if (isSuccess) {

                // Update cart badge if cart_quantity is provided
                if (result.cart_quantity !== undefined) {
                    updateCartBadge(result.cart_quantity);
                }

                // Success message will be shown by the other handler

                // Show proceed to payment button
                const proceedPaymentBtn = document.getElementById('proceedPaymentBtn');
                if (proceedPaymentBtn) proceedPaymentBtn.style.display = 'block';

                // Update cart preview
                if (typeof loadCartPreview === 'function') {
                    loadCartPreview();
                }

                // Reset button for next use
                if (addToCartBtn) {
                    addToCartBtn.disabled = false;
                    addToCartBtn.innerHTML = '<i class="fa fa-plus-circle"></i> ' + t('add_to_cart');
                }

                // Clear current selection and show success message
                setTimeout(() => {
                    resetAllSelections();
                    showMessage(t('appointment_added_cart'), 'success');

                    // Re-enable all services after successful appointment addition
                    enableAllServices();

                    // Hide loading screen after success message is shown
                    hideLoadingScreen();

                    // Show payment and back to categories buttons
                    document.getElementById('proceedPaymentBtn').style.display = 'block';
                    document.getElementById('backToCategoriesBtn').style.display = 'block';
                }, 2000);

            } else {
                // Hide loading screen on error
                hideLoadingScreen();

                // Show specific error message from server if available
                const errorMessage = result && result.error ? 
                    (typeof result.error === 'string' ? result.error : JSON.stringify(result.error)) : 
                    'Error adding to cart. Please try again.';
                showMessage(errorMessage, 'error');

                // Reset button on error
                if (addToCartBtn) {
                    addToCartBtn.disabled = false;
                    addToCartBtn.innerHTML = '<i class="fa fa-plus-circle"></i> ' + t('add_to_cart');
                }
            }
        })
        .catch(error => {
            // Hide loading screen on network error
            hideLoadingScreen();

            showMessage(t('error_adding_cart'), 'error');

            // Reset button on error
            if (addToCartBtn) {
                addToCartBtn.disabled = false;
                addToCartBtn.innerHTML = '<i class="fa fa-plus-circle"></i> ' + t('add_to_cart');
            }
        });
    }

    function showMessage(message, type = 'success') {
        // Create temporary message
        const messageDiv = document.createElement('div');
        const alertClass = type === 'error' ? 'alert-danger' : 'alert-success';
        const icon = type === 'error' ? '⚠️' : '✅';
        const title = type === 'error' ? 'Error!' : 'Success!';

        messageDiv.className = `alert ${alertClass} alert-dismissible fade show position-fixed`;
        messageDiv.style.cssText = 'top: 20px; right: 20px; z-index: 10000; min-width: 300px;';
        messageDiv.innerHTML = `
            <strong>${icon} ${title}</strong> ${message}
            <button type="button" class="close" data-dismiss="alert">
                <span>&times;</span>
            </button>
        `;

        document.body.appendChild(messageDiv);

        // Auto remove after 3 seconds
        setTimeout(() => {
            if (messageDiv.parentNode) {
                messageDiv.parentNode.removeChild(messageDiv);
            }
        }, 3000);
    }

    // Keep backward compatibility
    function showSuccessMessage(message) {
        showMessage(message, 'success');
    }


    // Filter Functions
    let originalEmployeeData = {}; // Store original employee data

    function populateFiltersWithAvailableEmployees() {
        const employeeFilter = document.getElementById('employeeFilter');
        const branchFilter = document.getElementById('branchFilter');

        if (!employeeFilter || !branchFilter) return;

        // Clear existing options
        employeeFilter.innerHTML = '<option value="">All Employees</option>';
        branchFilter.innerHTML = '<option value="">All Branches</option>';

        if (!currentEmployees || !selectedDate) {
            return;
        }

        const availableEmployees = new Set();
        const availableBranches = new Set();

        // Get employees who have available slots for the selected date
        Object.entries(currentEmployees).forEach(([employeeId, employee]) => {
            if (employee && employee.name) {
                // Check if this employee has slots for the selected date
                const hasSlots = currentSlots && currentSlots[employeeId] && 
                               Object.keys(currentSlots[employeeId]).length > 0;

                if (hasSlots || !currentSlots) { // Include all if no slot data yet
                    availableEmployees.add(employee.name);
                    if (employee.branch_name) {
                        availableBranches.add(employee.branch_name);
                    }
                }
            }
        });

        // Populate employee filter with available employees
        availableEmployees.forEach(employeeName => {
            const option = document.createElement('option');
            option.value = employeeName;
            option.textContent = employeeName;
            employeeFilter.appendChild(option);
        });

        // Populate branch filter with branches of available employees
        availableBranches.forEach(branchName => {
            const option = document.createElement('option');
            option.value = branchName;
            option.textContent = branchName;
            branchFilter.appendChild(option);
        });

    }

