    function hideFilters() {
        const appointmentFilters = document.getElementById('appointmentFilters');
        if (appointmentFilters) {
            appointmentFilters.style.display = 'none';
        }

        // Note: We don't hide calendarMainSection here because it contains other elements
        // like date selection that might still need to be visible
    }

    function populateFilters() {
        // Set flag to prevent filter change events from triggering loops
        isPopulatingFilters = true;

        try {
            // Store original data if not already stored and we have data
            if (currentEmployees && Object.keys(currentEmployees).length > 0) {
                if (Object.keys(originalEmployeeData).length === 0) {
                    originalEmployeeData = JSON.parse(JSON.stringify(currentEmployees));
                }
            }

            const employeeFilter = document.getElementById('employeeFilter');
            const branchFilter = document.getElementById('branchFilter');


            if (!employeeFilter || !branchFilter) {
                return;
            }

            // Store current selections before clearing
            const currentEmployeeSelection = employeeFilter.value;
            const currentBranchSelection = branchFilter.value;

            // Clear existing options except "All" option
            employeeFilter.innerHTML = '<option value="">All Employees</option>';
            branchFilter.innerHTML = '<option value="">All Branches</option>';

        // Only populate if we have employee data
        if (!currentEmployees || Object.keys(currentEmployees).length === 0) {
            return;
        }

        // Get unique employees and branches
        const employees = new Set();
        const branches = new Set();

        Object.values(currentEmployees).forEach(employee => {
            if (employee && employee.name) {
                employees.add(employee.name);
            }
            if (employee && employee.branch_name) {
                branches.add(employee.branch_name);
            }
        });


        // Populate employee filter
        employees.forEach(employeeName => {
            const option = document.createElement('option');
            option.value = employeeName;
            option.textContent = employeeName;
            employeeFilter.appendChild(option);
        });

        // Populate branch filter
        branches.forEach(branchName => {
            const option = document.createElement('option');
            option.value = branchName;
            option.textContent = branchName;
            branchFilter.appendChild(option);
        });

        // Restore previous selections if they still exist in the options
        if (currentEmployeeSelection) {
            employeeFilter.value = currentEmployeeSelection;
        }
        if (currentBranchSelection) {
            branchFilter.value = currentBranchSelection;
        }

        } catch (error) {
            console.error('❌ Error in populateFilters:', error);
        } finally {
            // Always reset the flag to allow future filtering
            isPopulatingFilters = false;
        }
    }

    // Flag to prevent infinite loops during filter population - moved above functions

    function filterAppointments() {
        // Prevent filtering during filter population to avoid loops
        if (isPopulatingFilters) {
            return;
        }

        const employeeFilter = document.getElementById('employeeFilter')?.value || '';
        const branchFilter = document.getElementById('branchFilter')?.value || '';


        // Start with original employee data
        let filteredEmployees = JSON.parse(JSON.stringify(originalEmployeeData));

        // Apply employee filter
        if (employeeFilter) {
            filteredEmployees = Object.fromEntries(
                Object.entries(filteredEmployees).filter(([id, employee]) =>
                    employee.name === employeeFilter
                )
            );
        }

        // Apply branch filter
        if (branchFilter) {
            filteredEmployees = Object.fromEntries(
                Object.entries(filteredEmployees).filter(([id, employee]) =>
                    employee.branch_name === branchFilter
                )
            );
        }

        // Update current employees and regenerate calendar
        currentEmployees = filteredEmployees;

        // Update headers and regenerate slots
        updateEmployeeHeaders();
        if (selectedDate) {
            generateSlots();
        }
    }
